window.CARDS=window.CARDS||{};CARDS["story-v-y1v5-index"]=[{"i":"sc-sudou-ken-y1v5-p11-1","v":"y1v5","y":1,"o":6,"k":"inner","w":"sudou-ken","q":"sudo ken ch 1  the soliloquy volume cold open  sudou s first person soliloquy alone with his backstory  no other character appears  and p 12 carries no prose   to be completely honest  i ain t really a capable person  his mother abandoned the family to go into the nightclub business  his father toiled as a janitor with a permanently hunched back  and the sight of it sickened him   being the idiot i am  i decided to give up on studyin  and go into sports    he chose getting stronger over studying and frames it as his own idea  not a defeat  solo sports first   tennis and pingpong  good but never top tier   then basketball  despite not being a team player he got seriously into it  kept improving  and was recommended to a high school with one of the best basketball teams in the entire country  the pulled recommendation defines his self read   that was when i really understood the painful truth  i was trash  born from trash  chose this school for what it promised   that was why i chose this school    free  and able to guarantee even his future  blank short scan page  running footer only  no prose to cite","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v5-p11-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sudou-ken.html#sc-sudou-ken-y1v5-p11-1\">Ch.1: the soliloquy<\/a><\/span><span class=\"meta\">Y1V5 · p.11–12<\/span><span class=\"by\">notes on <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/span><\/h3><p class=\"setup\">Volume cold open: Sudou’s first-person soliloquy alone with his backstory; no other character appears, and p.12 carries no prose.<\/p><ul class=\"lines\"><li class=\"q inner\"><b class=\"sp\">Sudō Ken<\/b> “To be completely honest, I ain’t really a capable person.”<span class=\"pg\">p.11<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Fact<\/span> His mother abandoned the family to go into the nightclub business; his father toiled as a janitor with a permanently hunched back, and the sight of it sickened him.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> “Being the idiot I am, I decided to give up on studyin’ and go into sports.” — he chose getting stronger over studying and frames it as his own idea, not a defeat.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Solo sports first — tennis and pingpong, good but never top-tier — then basketball: despite not being a team player he got seriously into it, kept improving, and was recommended to a high school with one of the best basketball teams in the entire country.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The pulled recommendation defines his self-read: “That was when I really understood the painful truth: I was trash, born from trash.”<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Chose this school for what it promised: “That was why I chose this school.” — free, and able to guarantee even his future.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Blank/short scan page: running footer only; no prose to cite.<span class=\"pg\">p.12<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p16-1\">→ After: Ch.2 §2.1: the huddle<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y1v5-p13-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"karuizawa-kei hirata-yousuke horikita-suzune sudou-ken ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 2  the zodiac debrief at pallet back table of the crowded cafe pallet after summer vacation  ayanokoji sits with hirata  karuizawa and horikita  reviewing the cruise ship zodiac exam and its hidden vips  the rabbit group read alphabetically   ayanokouji kun  ichinose san  ibuki san  karuizawa san   made him the rabbit vip  the dragon group s fifth name was kushida san   i honestly don t have a clue    lied to the group when horikita asked what he thought  notices karuizawa has started calling hirata yousuke kun  he meets her gaze and she diverts her eyes  plays along as the cooperative nobody while hirata works to cement the four person group  exchanges the no presence   long shadows banter with her  she is not joking when she takes the bait  names sudou among the athletic students the festival is built to give their first real opening","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v5-p13-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v5-p13-1\">Ch.2: the zodiac debrief at Pallet<\/a><\/span><span class=\"meta\">Y1V5 · p.13–15<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Back table of the crowded café Pallet after summer vacation: Ayanokōji sits with Hirata, Karuizawa and Horikita, reviewing the cruise-ship zodiac exam and its hidden VIPs.<\/p><p class=\"with\">with <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “I honestly don’t have a clue” — lied to the group when Horikita asked what he thought.<span class=\"pg\">p.14<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Fact<\/span> The rabbit group read alphabetically — Ayanokouji-kun, Ichinose-san, Ibuki-san, Karuizawa-san — made him the rabbit VIP; the dragon group’s fifth name was Kushida-san.<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Notices Karuizawa has started calling Hirata Yousuke-kun; he meets her gaze and she diverts her eyes.<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Plays along as the cooperative nobody while Hirata works to cement the four-person group.<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Exchanges the no-presence / long-shadows banter with her; she is not joking when she takes the bait.<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Names Sudou among the athletic students the festival is built to give their first real opening.<span class=\"pg\">p.16<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v5-p16-1\">→ After: Ch.2 §2.1: the rules and the huddle<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y1v5-p13-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"kushida-kikyou horikita-suzune hirata-yousuke","q":"hirata yosuke ch 2  the zodiac debrief at pallet at pallet he keeps the two girls  friction down   his presence makes the discomfort between karuizawa and horikita mysteriously disappear   i think ryuuen kun figured it all out in the middle of the test   if he understood the rules  he should have discovered all the vips   i m glad we re discussing this  horikita san and ayanokouji kun   i actually have a proposal   first  to bring our class together  i d like to rope in kushida san as an ally  proposes her as the fourth ally to unite the boys   starting with ike kun and yamauchi kun   over horikita s refusal  his proposal is rejected  she side eyes ayanokoji instead of softening","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y1v5-p13-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y1v5-p13-1\">Ch.2: the zodiac debrief at Pallet<\/a><\/span><span class=\"meta\">Y1V5 · p.13–15<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">At Pallet he keeps the two girls’ friction down — his presence makes the discomfort between Karuizawa and Horikita mysteriously disappear.<\/p><p class=\"with\">with <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “I think Ryuuen-kun figured it all out in the middle of the test,”<span class=\"pg\">p.13<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “If he understood the rules, he should have discovered all the VIPs,”<span class=\"pg\">p.14<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “I’m glad we’re discussing this, Horikita-san and Ayanokouji-kun,”<span class=\"pg\">p.14<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I actually have a proposal.”<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “First, to bring our class together, I’d like to rope in Kushida-san as an ally.”<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Proposes her as the fourth ally to unite the boys — starting with Ike-kun and Yamauchi-kun — over Horikita’s refusal.<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> His proposal is rejected; she side-eyes Ayanokōji instead of softening.<span class=\"pg\">p.15<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v5-p16-1\">→ After: Ch.2 §2.1: the briefing<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y1v5-p13-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"karuizawa-kei horikita-suzune","q":"horikita suzune ch 2  the zodiac debrief at pallet at pallet with hirata  karuizawa and ayanokoji  she walks the rabbit group through the alphabetical vip rule and the cruise ship exam s logic   if you put the names of the students in the rabbit group in alphabetical order  it would be ayanokouji kun  ichinose san  ibuki san  and then karuizawa san  confirms karuizawa s dragon group deduction   kushida fifth   and explains why the pattern was hard to see mid exam   though it appears that ryuuen kun rules class c alone  perhaps that isn t actually true   a rebellious student must ve tossed out the wrong answer in direct defiance of ryuuen kun   that said  you evaded ryuuen kun s clutches quite well    aims it at karuizawa   unnecessary    refuses hirata s proposal to rope kushida in   i won t deny the fact that she has certain skills  but we can do anything she can on our own   those who claim that they have no presence usually cast long shadows   do you take me for a fool    stung by ayanokoji s no presence bait  not joking","h":"<article class=\"card\" id=\"sc-horikita-suzune-y1v5-p13-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y1v5-p13-1\">Ch.2: the zodiac debrief at Pallet<\/a><\/span><span class=\"meta\">Y1V5 · p.13–15<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">At Pallet with Hirata, Karuizawa and Ayanokōji, she walks the rabbit group through the alphabetical VIP rule and the cruise-ship exam’s logic.<\/p><p class=\"with\">with <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “If you put the names of the students in the rabbit group in alphabetical order, it would be Ayanokouji-kun, Ichinose-san, Ibuki-san, and then Karuizawa-san,”<span class=\"pg\">p.13<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Though it appears that Ryuuen-kun rules Class C alone, perhaps that isn’t actually true.”<span class=\"pg\">p.14<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “A rebellious student must’ve tossed out the wrong answer in direct defiance of Ryuuen-kun.”<span class=\"pg\">p.14<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Confirms Karuizawa’s dragon-group deduction — Kushida fifth — and explains why the pattern was hard to see mid-exam.<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That said, you evaded Ryuuen-kun’s clutches quite well.” — aims it at Karuizawa.<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Unnecessary,” — refuses Hirata’s proposal to rope Kushida in.<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I won’t deny the fact that she has certain skills, but we can do anything she can on our own.”<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Those who claim that they have no presence usually cast long shadows,”<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you take me for a fool?” — stung by Ayanokōji’s no-presence bait; not joking.<span class=\"pg\">p.15<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v5-p16-1\">→ After: Ch.2 §2.1: the briefing and the huddle<\/button><\/div><\/article>"},{"i":"sc-ibuki-mio-y1v5-p13-1","v":"y1v5","y":1,"o":6,"k":"","w":"horikita-suzune ibuki-mio","q":"ibuki mio ch 2  passing mention named in the alphabetical rabbit group roster karuizawa recites   third  between ichinose san and karuizawa san  her place in the roster is the exhibit for the zodiac vip rule","h":"<article class=\"card\" id=\"sc-ibuki-mio-y1v5-p13-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ibuki-mio.html#sc-ibuki-mio-y1v5-p13-1\">Ch.2: passing mention<\/a><\/span><span class=\"meta\">Y1V5 · p.13<\/span><span class=\"by\">notes on <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/span><\/h3><p class=\"setup\">Named in the alphabetical rabbit-group roster Karuizawa recites — third, between Ichinose-san and Karuizawa-san.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Her place in the roster is the exhibit for the zodiac VIP rule.<span class=\"pg\">p.13<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-karuizawa-kei-y1v5-p13-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"horikita-suzune hirata-yousuke ayanokouji-kiyotaka karuizawa-kei","q":"karuizawa kei ch 2  the zodiac debrief at pallet at pallet she works through the rabbit group s alphabetical vip order and lands on her own role in the cruise ship exam   that s why i was chosen as vip   but isn t that really  really simple    on the dragon group s fifth name giveaway for kushida  sits with her at pallet   the two girls are completely incompatible at first glance  but hirata s presence erases the discomfort  has started calling him yousuke kun  hugs his arm  and asks him to confirm her poker face   ayanokoji notices the shift   i do have a surprisingly good poker face  keeps her eyes on him after the others lose interest  he meets her gaze and she diverts hers","h":"<article class=\"card\" id=\"sc-karuizawa-kei-y1v5-p13-1\"><h3><span class=\"ttl\"><a href=\"../../../people/karuizawa-kei.html#sc-karuizawa-kei-y1v5-p13-1\">Ch.2: the zodiac debrief at Pallet<\/a><\/span><span class=\"meta\">Y1V5 · p.13–15<\/span><span class=\"by\">notes on <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/span><\/h3><p class=\"setup\">At Pallet she works through the rabbit group’s alphabetical VIP order and lands on her own role in the cruise-ship exam.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> “That’s why I was chosen as VIP”<span class=\"pg\">p.13<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> “But isn’t that really, really simple?” — on the dragon group’s fifth-name giveaway for Kushida.<span class=\"pg\">p.13<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> “I do have a surprisingly good poker face.”<span class=\"pg\">p.14<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Sits with her at Pallet — the two girls are completely incompatible at first glance, but Hirata’s presence erases the discomfort.<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Has started calling him Yousuke-kun, hugs his arm, and asks him to confirm her poker face — Ayanokōji notices the shift.<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Keeps her eyes on him after the others lose interest; he meets her gaze and she diverts hers.<span class=\"pg\">p.14<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-karuizawa-kei-y1v5-p28-1\">→ After: Ch.2 §2.2: the Class C exit<\/button><\/div><\/article>"},{"i":"sc-kushida-kikyou-y1v5-p13-1","v":"y1v5","y":1,"o":6,"k":"","w":"horikita-suzune hirata-yousuke sakayanagi-arisu kushida-kikyou","q":"kushida kikyo ch 2  passing mentions named in the zodiac recap as the dragon group s fifth name and therefore its vip  again at p 15 as hirata s proposed ally and at p 30 as a beauty benchmark  her name is the exhibit for the alphabetical vip rule horikita walks through  hirata wants her roped in to unite the boys  horikita refuses  sakayanagi is called  as cute as kushida and sakura  in narration","h":"<article class=\"card\" id=\"sc-kushida-kikyou-y1v5-p13-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kushida-kikyou.html#sc-kushida-kikyou-y1v5-p13-1\">Ch.2: passing mentions<\/a><\/span><span class=\"meta\">Y1V5 · p.13, 15, 30<\/span><span class=\"by\">notes on <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a><\/span><\/h3><p class=\"setup\">Named in the zodiac recap as the dragon group’s fifth name and therefore its VIP; again at p.15 as Hirata’s proposed ally and at p.30 as a beauty benchmark.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Her name is the exhibit for the alphabetical VIP rule Horikita walks through.<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Hirata wants her roped in to unite the boys; Horikita refuses.<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Sakayanagi is called “as cute as Kushida and Sakura” in narration.<span class=\"pg\">p.30<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kushida-kikyou-y1v5-p39-1\">→ After: Ch.3 §3: Asked for the middle ground<\/button><\/div><\/article>"},{"i":"sc-sports-festival-y1v5-p16-1","v":"y1v5","y":1,"o":6,"k":"","w":"horikita-suzune chabashira-sae","q":"sports festival ch 2  2 1  the rules briefing chabashira s two hour homeroom hands out the printed sports festival rules  september to early october becomes heavy physical education  classes a and d form the red team  classes b and c the white team  across all grade levels  class d competes alongside class a  individual events score 15 12 10 8  fifth place loses one point and each place below loses one more  a team competition win is worth 500  recommended participant events score 50 30 15 10  fifth loses two points and each place below loses two more  the 1200 metre relay pays three times those values  after combined class scores are reviewed  100 class points are deducted from the first  second  and third year batches of the two classes on the losing team  chabashira adds that points move class by class  not just by team  even a red team win can still hit class d with the 100 point penalty if it holds the lowest combined overall score  grade ranking is separate  50 class points to each grade s first place class  no change for second  50 deducted for third  100 for fourth  an individual winner chooses 5000 private points or three written test points  second chooses 3000 or two  third chooses 1000 or one  test points taken this way cannot be given to another student  the lowest scorer in an individual competition loses 1000 private points  or one written test point if they hold fewer than 1000  overall mvp takes 100 000 private points  each grade s top three scorers take 10 000 private points apiece  the ten lowest scoring students in each year lose ten points on their next written exam  thirteen events in order  100 metre dash  hurdle race  capture the flag  boys  ball toss  girls  tug of war by sex  obstacle course race  three legged race  cavalry battle  200 metre dash  then scavenger hunt  four way tug of war  mixed three legged race  and the mixed grade 1200 metre relay  the participation table must be a class consensus  the window opens one week before the festival and closes at 5 00 pm the day before  a missed window means random assignment  falling below the minimum for an all participant event means disqualification  a recommended event substitute can be bought for 100 000 private points per competition  her absence and health questions draw out the substitute price and the student decides health policy  delivers the whole briefing in a detached  matter of fact manner and lets out one slight laugh at ike s question","h":"<article class=\"card\" id=\"sc-sports-festival-y1v5-p16-1\"><h3><span class=\"ttl\"><a href=\"../../../school/exam/sports-festival.html#sc-sports-festival-y1v5-p16-1\">Ch.2 §2.1: the rules briefing<\/a><\/span><span class=\"meta\">Y1V5 · p.16–23<\/span><span class=\"by\">notes on <a href=\"../../../school/exam/sports-festival.html\">Sports Festival<\/a><\/span><\/h3><p class=\"setup\">Chabashira’s two-hour homeroom hands out the printed sports festival rules; September to early October becomes heavy physical education.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a><\/p><details class=\"more\"><summary>15 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Rule<\/span> Classes A and D form the Red Team, Classes B and C the White Team, across all grade levels; Class D competes alongside Class A.<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> Individual events score 15/12/10/8; fifth place loses one point and each place below loses one more; a team-competition win is worth 500.<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> Recommended-participant events score 50/30/15/10; fifth loses two points and each place below loses two more; the 1200-metre relay pays three times those values.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> After combined class scores are reviewed, 100 class points are deducted from the first-, second- and third-year batches of the two classes on the losing team.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Chabashira adds that points move class-by-class, not just by team: even a Red Team win can still hit Class D with the 100-point penalty if it holds the lowest combined overall score.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> Grade ranking is separate: 50 class points to each grade’s first-place class, no change for second, 50 deducted for third, 100 for fourth.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> An individual winner chooses 5000 private points or three written-test points, second chooses 3000 or two, third chooses 1000 or one; test points taken this way cannot be given to another student.<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> The lowest scorer in an individual competition loses 1000 private points, or one written-test point if they hold fewer than 1000.<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> Overall MVP takes 100,000 private points; each grade’s top three scorers take 10,000 private points apiece.<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> The ten lowest-scoring students in each year lose ten points on their next written exam.<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> Thirteen events in order: 100-metre dash, hurdle race, capture the flag (boys), ball toss (girls), tug-of-war by sex, obstacle course race, three-legged race, cavalry battle, 200-metre dash; then scavenger hunt, four-way tug-of-war, mixed three-legged race, and the mixed-grade 1200-metre relay.<span class=\"pg\">p.21<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> The participation table must be a class consensus; the window opens one week before the festival and closes at 5:00 pm the day before; a missed window means random assignment.<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> Falling below the minimum for an all-participant event means disqualification; a recommended-event substitute can be bought for 100,000 private points per competition.<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Her absence and health questions draw out the substitute price and the student-decides health policy.<span class=\"pg\">p.22–23<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Chabashira Sae<\/b> Delivers the whole briefing in a detached, matter-of-fact manner and lets out one slight laugh at Ike’s question.<span class=\"pg\">p.16<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sports-festival-y1v5-p26-1\">→ After: Ch.2 §2.2: the assembly<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y1v5-p16-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"horikita-suzune ike-kanji yamauchi-haruki ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 2  2 1  the rules and the huddle afternoon homeroom becomes a two hour session  chabashira announces the september sports festival and its handout  the class erupts  teases her about finally having an opportunity to get in touch with her brother on the red team  she glares and tells him to drop it   at least you have an opportunity to get in touch now  huh  watches the huddle from the side   ike and yamauchi push for personal chances against the class s interest  yamauchi is present at the huddle  no line of his is tagged in the translation   it s a sad fact of reality    answering horikita s complaint that only guys like these come to her","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v5-p16-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v5-p16-1\">Ch.2 §2.1: the rules and the huddle<\/a><\/span><span class=\"meta\">Y1V5 · p.16–25<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Afternoon homeroom becomes a two-hour session: Chabashira announces the September sports festival and its handout; the class erupts.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a> · <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “At least you have an opportunity to get in touch now, huh?”<span class=\"pg\">p.17<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “It’s a sad fact of reality,” — answering Horikita’s complaint that only guys like these come to her.<span class=\"pg\">p.23<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Teases her about finally having an opportunity to get in touch with her brother on the Red Team; she glares and tells him to drop it.<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Watches the huddle from the side — Ike and Yamauchi push for personal chances against the class’s interest.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> Yamauchi is present at the huddle; no line of his is tagged in the translation.<span class=\"pg\">p.24<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v5-p13-1\">← Before: Ch.2: the zodiac debrief at Pallet<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v5-p26-1\">→ After: Ch.2 §2.2: the Red Team assembly<\/button><\/div><\/article>"},{"i":"sc-chabashira-sae-y1v5-p16-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"chabashira-sae","q":"chabashira sae ch 2  2 1  the sports festival briefing afternoon homeroom runs two hours  she distributes the festival handout and weekly schedules in a detached  matter of fact manner   however  from september to the beginning of october  we will be holding more physical education classes to prepare for the school sports festival   in any case  this event will massively impact each and every class    answers hirata s special exam question vaguely  explains the red white split   class d and class a ride the red team together   you in class d are assigned to the red team   their reward will be not having any points deducted    the cruel  brief answer to the winning team question   in the sports festival  you can earn test points as a prize  which you can then apply to a written exam    lets out a slight laugh  an unusual sight  reads out the ten lowest penalty  for first years  ten points off the next written exam   should you fall short of the minimum required number of people for competitions for all participants  you will be deemed unable to continue and disqualified   a substitute requires 100 000 private points per competition   next period s location will move to gymnasium 1  where you ll meet with students from other classes and grade levels","h":"<article class=\"card\" id=\"sc-chabashira-sae-y1v5-p16-1\"><h3><span class=\"ttl\"><a href=\"../../../people/chabashira-sae.html#sc-chabashira-sae-y1v5-p16-1\">Ch.2 §2.1: the sports festival briefing<\/a><\/span><span class=\"meta\">Y1V5 · p.16–25<\/span><span class=\"by\">notes on <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a><\/span><\/h3><p class=\"setup\">Afternoon homeroom runs two hours: she distributes the festival handout and weekly schedules in a detached, matter-of-fact manner.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Chabashira Sae<\/b> “However, from September to the beginning of October, we will be holding more physical education classes to prepare for the school sports festival.”<span class=\"pg\">p.16<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Chabashira Sae<\/b> “In any case, this event will massively impact each and every class.” — answers Hirata’s special-exam question vaguely.<span class=\"pg\">p.16<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Chabashira Sae<\/b> “You in Class D are assigned to the Red Team.”<span class=\"pg\">p.17<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Post<\/span> Explains the Red/White split — Class D and Class A ride the Red Team together.<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Their reward will be not having any points deducted.” — the cruel, brief answer to the winning-team question.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In the sports festival, you can earn test points as a prize, which you can then apply to a written exam.” — lets out a slight laugh, an unusual sight.<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Post<\/span> Reads out the ten-lowest penalty: for first-years, ten points off the next written exam.<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Should you fall short of the minimum required number of people for competitions for all participants, you will be deemed unable to continue and disqualified,”<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A substitute requires 100,000 private points per competition.”<span class=\"pg\">p.23<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Next period’s location will move to Gymnasium 1, where you’ll meet with students from other classes and grade levels.”<span class=\"pg\">p.23<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-chabashira-sae-y1v5-p35-1\">→ After: Ch.2 §2.3: the gate<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y1v5-p16-1","v":"y1v5","y":1,"o":6,"k":"action spoken","w":"hirata-yousuke","q":"hirata yosuke ch 2  2 1  the briefing in homeroom he is the first to ask whether the festival is another special exam  chabashira s answer stays vague   sensei  is this festival another of the special exams   um  sensei  how many points does the winning team get    chabashira answers  none   wait  so  we can decide the order in which we ll participate    on the participation table  the absence questions in the room are his and horikita s   both read the handout like exam material","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y1v5-p16-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y1v5-p16-1\">Ch.2 §2.1: the briefing<\/a><\/span><span class=\"meta\">Y1V5 · p.16–25<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">In homeroom he is the first to ask whether the festival is another special exam; Chabashira’s answer stays vague.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “Sensei, is this festival another of the special exams?”<span class=\"pg\">p.16<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “Um, sensei, how many points does the winning team get?” — Chabashira answers: none.<span class=\"pg\">p.18<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “Wait. So, we can decide the order in which we’ll participate?” — on the participation table.<span class=\"pg\">p.22<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> The absence questions in the room are his and Horikita’s — both read the handout like exam material.<span class=\"pg\">p.22<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v5-p13-1\">← Before: Ch.2: the zodiac debrief at Pallet<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v5-p26-1\">→ After: Ch.2 §2.2: the assembly<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y1v5-p16-1","v":"y1v5","y":1,"o":6,"k":"action spoken","w":"horikita-manabu horikita-suzune","q":"horikita suzune ch 2  2 1  the briefing and the huddle in homeroom she spots the testing method on the handout before most of the class and calls ayanokoji over  at the mention that class a   her brother s year   rides the same red team  she mutters at ayanokoji to drop it   don t talk about that here  after hirata s practical questions she raises her own  what happens on the day if someone is absent from a group competition   well  how many points are needed to assign a substitute  sudou  ike and yamauchi corner her in the free homeroom period to argue the festival strategy   why do only guys like these come to me   that s not a valid opinion    shuts down ike s fun and win line at once   within our class  you stand out as someone with superior athletic skill    concedes sudou s claim on the recommended events   stamina isn t an unlimited resource    her counter to entering sudou in everything   we re not coming to any decisions right now    ends the huddle without a decision","h":"<article class=\"card\" id=\"sc-horikita-suzune-y1v5-p16-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y1v5-p16-1\">Ch.2 §2.1: the briefing and the huddle<\/a><\/span><span class=\"meta\">Y1V5 · p.16–25<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">In homeroom she spots the testing method on the handout before most of the class and calls Ayanokōji over. Sudou, Ike and Yamauchi corner her in the free homeroom period to argue the festival strategy.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Don’t talk about that here,”<span class=\"pg\">p.17<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Well, how many points are needed to assign a substitute?”<span class=\"pg\">p.23<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Why do only guys like these come to me?”<span class=\"pg\">p.23<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> At the mention that Class A — her brother’s year — rides the same Red Team, she mutters at Ayanokōji to drop it.<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> After Hirata’s practical questions she raises her own: what happens on the day if someone is absent from a group competition?<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s not a valid opinion.” — shuts down Ike’s fun-and-win line at once.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Within our class, you stand out as someone with superior athletic skill.” — concedes Sudou’s claim on the recommended events.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Stamina isn’t an unlimited resource.” — her counter to entering Sudou in everything.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We’re not coming to any decisions right now.” — ends the huddle without a decision.<span class=\"pg\">p.25<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v5-p13-1\">← Before: Ch.2: the zodiac debrief at Pallet<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v5-p26-1\">→ After: Ch.2 §2.2: the assembly and the coin<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v5-p16-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"horikita-suzune ike-kanji sudou-ken","q":"sudo ken ch 2  2 1  the huddle named as one of the athletic students fired up by the sports festival   probably the first exam that lets him contribute meaningfully  his athletic ability is the class s read on him before the events are even set  pulls ike and yamauchi to her and opens the strategy huddle   let s figure this out  horikita   class d can win this   if i do that  we ll win    claims every recommended participant event  tells ike flatly that the recommended events belong to people who are good at sports   you re not  kanji  pushes back on her stamina caution   even tired  he moves better than the unathletic guys   and leaves without a decision   but it s better to leave it to me than put forward someone unathletic  right","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v5-p16-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sudou-ken.html#sc-sudou-ken-y1v5-p16-1\">Ch.2 §2.1: the huddle<\/a><\/span><span class=\"meta\">Y1V5 · p.16, 23–25<\/span><span class=\"by\">notes on <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/span><\/h3><p class=\"setup\">Named as one of the athletic students fired up by the sports festival — probably the first exam that lets him contribute meaningfully.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “Let’s figure this out, Horikita,”<span class=\"pg\">p.23<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “Class D can win this,”<span class=\"pg\">p.24<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “If I do that, we’ll win,” — claims every recommended-participant event.<span class=\"pg\">p.24<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Feat<\/span> His athletic ability is the class’s read on him before the events are even set.<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Pulls Ike and Yamauchi to her and opens the strategy huddle.<span class=\"pg\">p.23<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Tells Ike flatly that the recommended events belong to people who are good at sports.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re not, Kanji,”<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Pushes back on her stamina caution — even tired, he moves better than the unathletic guys — and leaves without a decision.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But it’s better to leave it to me than put forward someone unathletic, right?”<span class=\"pg\">p.24<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p11-1\">← Before: Ch.1: the soliloquy<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p39-1\">→ After: Ch.3 §3: The ability camp, then the grip-strength king<\/button><\/div><\/article>"},{"i":"sc-ike-kanji-y1v5-p17-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"sudou-ken yamauchi-haruki sakayanagi-arisu ike-kanji","q":"ike kanji ch 2  the briefing and the huddle shouts at the red white announcement  then joins sudou and yamauchi in crowding horikita for strategy   whoa  seriously  we re really doing that   yeah  yeah  let s think of a way to win   i d like to have fun and win    smacked down by horikita at once   hey  you don t know that for sure    miracles happen  and it should be fair  takes sudou s  you re not  kanji  without an answer  frustrated but silent by the end of the huddle  the pair are dissatisfied together  the translation never tags which boy speaks the  we want a chance  lines  whispers  hey  check out that girl  pointing at the class a girl with the cane   he s smitten like the rest   hey  check out that girl","h":"<article class=\"card\" id=\"sc-ike-kanji-y1v5-p17-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ike-kanji.html#sc-ike-kanji-y1v5-p17-1\">Ch.2: the briefing and the huddle<\/a><\/span><span class=\"meta\">Y1V5 · p.17, 23–27<\/span><span class=\"by\">notes on <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a><\/span><\/h3><p class=\"setup\">Shouts at the Red/White announcement, then joins Sudou and Yamauchi in crowding Horikita for strategy.<\/p><p class=\"with\">with <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a> · <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ike Kanji<\/b> “Whoa! Seriously?! We’re really doing that?”<span class=\"pg\">p.17<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ike Kanji<\/b> “Yeah, yeah, let’s think of a way to win!”<span class=\"pg\">p.23<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ike Kanji<\/b> “I’d like to have fun and win!” — smacked down by Horikita at once.<span class=\"pg\">p.24<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Hey, you don’t know that for sure!” — miracles happen, and it should be fair.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Takes Sudou’s “You’re not, Kanji,” without an answer; frustrated but silent by the end of the huddle.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> The pair are dissatisfied together; the translation never tags which boy speaks the “we want a chance” lines.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Whispers “Hey, check out that girl,” pointing at the Class A girl with the cane — he’s smitten like the rest.<span class=\"pg\">p.27<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey, check out that girl,”<span class=\"pg\">p.27<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ike-kanji-y1v5-p39-1\">→ After: Ch.3 §3: Grip strength and the scavenger hunt<\/button><\/div><\/article>"},{"i":"sc-private-points-y1v5-p17-1","v":"y1v5","y":1,"o":6,"k":"","w":"","q":"private points ch 2  the sports festival s point economy chabashira s handout prices the school sports festival in private points  test points and class points at once  individual competition placement pays 15 12 10 8 points on the class scoreboard  fifth place loses one point  and each place below loses one more  recommended participant events pay 50 30 15 10  fifth place loses two points  each place below loses two more  the relay pays three times those values  the winning team of a team competition takes 500 points  after combined class scores are reviewed  100 class points are deducted from the first  second  and third year batches of the two classes on the losing team  chabashira adds that points move class by class  not just by team  grade ranking is separate  50 class points to each grade s first place class  no change for second  50 deducted for third  100 for fourth  first place in an individual competition chooses 5000 private points or three written test points  second chooses 3000 or two  third chooses 1000 or one   test points accepted this way cannot be given to another student  the lowest scorer in an individual competition loses 1000 private points  or one written test point if they have fewer than 1000  overall mvp  100 000 private points  each grade s top three scorers  10 000 private points apiece  the ten lowest scoring students in each year lose ten points on their next written exam   for first years the penalty is a written exam deduction  a substitute for a recommended participant event costs 100 000 private points per competition","h":"<article class=\"card\" id=\"sc-private-points-y1v5-p17-1\"><h3><span class=\"ttl\"><a href=\"../../../school/system/private-points.html#sc-private-points-y1v5-p17-1\">Ch.2: the sports festival’s point economy<\/a><\/span><span class=\"meta\">Y1V5 · p.17–23<\/span><span class=\"by\">notes on <a href=\"../../../school/system/private-points.html\">Private Points<\/a><\/span><\/h3><p class=\"setup\">Chabashira’s handout prices the school sports festival in private points, test points and class points at once.<\/p><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Rule<\/span> Individual competition placement pays 15/12/10/8 points on the class scoreboard; fifth place loses one point, and each place below loses one more.<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> Recommended-participant events pay 50/30/15/10; fifth place loses two points, each place below loses two more; the relay pays three times those values; the winning team of a team competition takes 500 points.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> After combined class scores are reviewed, 100 class points are deducted from the first-, second- and third-year batches of the two classes on the losing team; Chabashira adds that points move class-by-class, not just by team.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> Grade ranking is separate: 50 class points to each grade’s first-place class, no change for second, 50 deducted for third, 100 for fourth.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> First place in an individual competition chooses 5000 private points or three written-test points; second chooses 3000 or two; third chooses 1000 or one — test points accepted this way cannot be given to another student.<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> The lowest scorer in an individual competition loses 1000 private points, or one written-test point if they have fewer than 1000.<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> Overall MVP: 100,000 private points; each grade’s top three scorers: 10,000 private points apiece.<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> The ten lowest-scoring students in each year lose ten points on their next written exam — for first-years the penalty is a written-exam deduction.<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> A substitute for a recommended-participant event costs 100,000 private points per competition.<span class=\"pg\">p.23<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-private-points-y1v5-p39-1\">→ After: Ch.3 §3: Class D’s festival point compromise<\/button><\/div><\/article>"},{"i":"sc-yamauchi-haruki-y1v5-p23-1","v":"y1v5","y":1,"o":6,"k":"","w":"ike-kanji sudou-ken yamauchi-haruki","q":"yamauchi haruki ch 2  2 1  the huddle gathers with sudou and ike around horikita the moment free homeroom starts  the pair voice the demand for a personal shot at points  only ike s lines are tagged by the translation  sudou s recommended events claim brushes them off  he and ike appear frustrated but say nothing  the  we want a chance  speeches sit untagged between horikita and sudou   the translation does not say whether ike or yamauchi speaks them","h":"<article class=\"card\" id=\"sc-yamauchi-haruki-y1v5-p23-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yamauchi-haruki.html#sc-yamauchi-haruki-y1v5-p23-1\">Ch.2 §2.1: the huddle<\/a><\/span><span class=\"meta\">Y1V5 · p.23–25<\/span><span class=\"by\">notes on <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a><\/span><\/h3><p class=\"setup\">Gathers with Sudou and Ike around Horikita the moment free homeroom starts.<\/p><p class=\"with\">with <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> The pair voice the demand for a personal shot at points; only Ike’s lines are tagged by the translation.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Sudou’s recommended-events claim brushes them off; he and Ike appear frustrated but say nothing.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The “we want a chance” speeches sit untagged between Horikita and Sudou — the translation does not say whether Ike or Yamauchi speaks them.<span class=\"pg\">p.24<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamauchi-haruki-y1v5-p54-1\">→ After: Ch.4 §4: On the losing end of the demo<\/button><\/div><\/article>"},{"i":"sc-sports-festival-y1v5-p26-1","v":"y1v5","y":1,"o":6,"k":"","w":"fujimaki katsuragi-kouhei ryuuen-kakeru ichinose-honami","q":"sports festival ch 2  2 2  the assembly gymnasium 1  four hundred strong  fujimaki briefs the red team  first year class a assembles under katsuragi  class c walks out  sakayanagi is introduced  and the class a class d pact is struck  only the final event   the 1200 metre relay   brings all classes from all grade levels together  every other event is divided by grade level  third year class a takes red team command in place of the student council president  class a and class d agree to keep out of each other s way  no shared competition details  only a meeting to come for the group events  ryuuen refuses class b s cooperation talk and walks class c out   the white team s first year halves open the festival estranged  ichinose confronts the walkout to his face and gets gratitude for the trouble saved","h":"<article class=\"card\" id=\"sc-sports-festival-y1v5-p26-1\"><h3><span class=\"ttl\"><a href=\"../../../school/exam/sports-festival.html#sc-sports-festival-y1v5-p26-1\">Ch.2 §2.2: the assembly<\/a><\/span><span class=\"meta\">Y1V5 · p.26–34<\/span><span class=\"by\">notes on <a href=\"../../../school/exam/sports-festival.html\">Sports Festival<\/a><\/span><\/h3><p class=\"setup\">Gymnasium 1, four hundred strong: Fujimaki briefs the Red Team, first-year Class A assembles under Katsuragi, Class C walks out, Sakayanagi is introduced, and the Class A–Class D pact is struck.<\/p><p class=\"with\">with <a href=\"../../../people/index.html#fujimaki\">Fujimaki<\/a> · <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Rule<\/span> Only the final event — the 1200-metre relay — brings all classes from all grade levels together; every other event is divided by grade level.<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Fujimaki<\/b> Third-year Class A takes Red Team command in place of the student council president.<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Class A and Class D agree to keep out of each other’s way: no shared competition details, only a meeting to come for the group events.<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Ryuuen refuses Class B’s cooperation talk and walks Class C out — the White Team’s first-year halves open the festival estranged.<span class=\"pg\">p.27<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Ichinose confronts the walkout to his face and gets gratitude for the trouble saved.<span class=\"pg\">p.27<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sports-festival-y1v5-p16-1\">← Before: Ch.2 §2.1: the rules briefing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sports-festival-y1v5-p39-1\">→ After: Ch.3 §3: Four-way tug-of-war and the luck events<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y1v5-p26-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"horikita-manabu katsuragi-kouhei sakayanagi-arisu ichinose-honami ryuuen-kakeru ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 2  2 2  the red team assembly over four hundred people gather in gymnasium 1  fujimaki takes red team command  first year class a assembles under katsuragi  ryuuen walks class c out  sakayanagi arisu is introduced  and ayanokoji and horikita argue strategy in the corner  notes that the student council president does not take red team command and wonders when he will make a move  takes the class a class d pact at face value   no shared competition details  only a promise not to get in each other s way  reads the gym s layout  a clear line between katsuragi s followers and nearly all the students sitting with sakayanagi  reconsiders which faction is superior  cites her as the kind who might put feelings aside for victory if ryuuen and class b reconcile  warns horikita that ryuuen likely already has one or more tactics in mind for the festival   the school has never once called the festival a  special exam   i think the sports festival is supposed to do the same with our physical abilities   you re looking for loopholes   you re not thinking big enough    his read on horikita s tunnel vision   we need to make sure that we re prepared  that s all there is to it   there s a good chance that he has a plan in place   we have to think like that to rise to class a s level  has studied ryuuen s strategies and thought processes ever since the fight that nearly got sudou expelled","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v5-p26-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v5-p26-1\">Ch.2 §2.2: the Red Team assembly<\/a><\/span><span class=\"meta\">Y1V5 · p.26–34<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Over four hundred people gather in Gymnasium 1: Fujimaki takes Red Team command, first-year Class A assembles under Katsuragi, Ryuuen walks Class C out, Sakayanagi Arisu is introduced, and Ayanokōji and Horikita argue strategy in the corner.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “The school has never once called the festival a ‘special exam.’”<span class=\"pg\">p.32<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “I think the sports festival is supposed to do the same with our physical abilities.”<span class=\"pg\">p.32<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “You’re looking for loopholes.”<span class=\"pg\">p.33<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Notes that the student council president does not take Red Team command and wonders when he will make a move.<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Takes the Class A–Class D pact at face value — no shared competition details, only a promise not to get in each other’s way.<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Reads the gym’s layout: a clear line between Katsuragi’s followers and nearly all the students sitting with Sakayanagi; reconsiders which faction is superior.<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Cites her as the kind who might put feelings aside for victory if Ryuuen and Class B reconcile.<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Warns Horikita that Ryuuen likely already has one or more tactics in mind for the festival.<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re not thinking big enough,” — his read on Horikita’s tunnel vision.<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We need to make sure that we’re prepared. That’s all there is to it,”<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There’s a good chance that he has a plan in place.”<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We have to think like that to rise to Class A’s level,”<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Has studied Ryuuen’s strategies and thought processes ever since the fight that nearly got Sudou expelled.<span class=\"pg\">p.34<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v5-p16-1\">← Before: Ch.2 §2.1: the rules and the huddle<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v5-p35-1\">→ After: Ch.2 §2.3: the gate<\/button><\/div><\/article>"},{"i":"sc-fujimaki-y1v5-p26-1","v":"y1v5","y":1,"o":6,"k":"action spoken","w":"horikita-manabu fujimaki","q":"fujimaki ch 2  2 2  red team command steps forward in the crowded gymnasium 1 among instructors and students and takes command of the red team for the sports festival   i m fujimaki  from the third year class a  announced as the student who will assume command of red team   the student council president does not take it   however  each and every one of them is a crucial battle in which you stake your survival at this school    his warning that future exams wear games  clothes   the only competition which all classes from all grade levels will participate in together is the final event the 1200 meter relay race  releases the first years to gather and discuss strategies by grade level  starting immediately  takes the command the student council president declined  ayanokoji notes the absence and wonders when he will move  no first name is printed anywhere in the chapter","h":"<article class=\"card\" id=\"sc-fujimaki-y1v5-p26-1\"><h3><span class=\"ttl\">Ch.2 §2.2: Red Team command<\/span><span class=\"meta\">Y1V5 · p.26–27<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#fujimaki\">Fujimaki<\/a><\/span><\/h3><p class=\"setup\">Steps forward in the crowded Gymnasium 1 among instructors and students and takes command of the Red Team for the sports festival.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Fujimaki<\/b> “I’m Fujimaki, from the third-year Class A.”<span class=\"pg\">p.26<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Fujimaki<\/b> “However, each and every one of them is a crucial battle in which you stake your survival at this school,” — his warning that future exams wear games’ clothes.<span class=\"pg\">p.26<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Fujimaki<\/b> “The only competition which all classes from all grade levels will participate in together is the final event—the 1200-meter relay race.”<span class=\"pg\">p.26<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Post<\/span> Announced as the student who will assume command of Red Team — the student council president does not take it.<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Releases the first-years to gather and discuss strategies by grade level, starting immediately.<span class=\"pg\">p.27<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Takes the command the student council president declined; Ayanokōji notes the absence and wonders when he will move.<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> No first name is printed anywhere in the chapter.<span class=\"pg\">p.26<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-hirata-yousuke-y1v5-p26-1","v":"y1v5","y":1,"o":6,"k":"action spoken","w":"katsuragi-kouhei sakayanagi-arisu hirata-yousuke","q":"hirata yosuke ch 2  2 2  the assembly meets katsuragi at the red team assembly and becomes class d s negotiating face   i look forward to working with you  accepts the keep out of each other s way pact   no shared competition details   and thanks him with  i m counting on you   it s pretty hard to trust other people in this school  katsuragi kun   so  you won t share any details about the competitions you re participating in  reassures her when she apologizes for being consistently absent   you have nothing to apologize for  looks to the rest of the class for the pact s final decision  no one objects","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y1v5-p26-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y1v5-p26-1\">Ch.2 §2.2: the assembly<\/a><\/span><span class=\"meta\">Y1V5 · p.26–34<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">Meets Katsuragi at the Red Team assembly and becomes Class D’s negotiating face.<\/p><p class=\"with\">with <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “I look forward to working with you,”<span class=\"pg\">p.27<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “It’s pretty hard to trust other people in this school, Katsuragi-kun.”<span class=\"pg\">p.31<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “So, you won’t share any details about the competitions you’re participating in?”<span class=\"pg\">p.31<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Accepts the keep-out-of-each-other’s-way pact — no shared competition details — and thanks him with “I’m counting on you.”<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Reassures her when she apologizes for being consistently absent.<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You have nothing to apologize for.”<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Looks to the rest of the class for the pact’s final decision; no one objects.<span class=\"pg\">p.31<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v5-p16-1\">← Before: Ch.2 §2.1: the briefing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v5-p39-1\">→ After: Ch.3 §3: Runs the homeroom, the vote and the roster<\/button><\/div><\/article>"},{"i":"sc-horikita-manabu-y1v5-p26-1","v":"y1v5","y":1,"o":6,"k":"","w":"horikita-suzune fujimaki horikita-manabu","q":"horikita manabu ch 2  passing mention named as the third year class a student and student council president suzune is scanning for  he does not take red team command  she has never sought him out first   he always initiates contact   and cannot find him in the four hundred strong crowd  fujimaki s command of the red team makes ayanokoji wonder when the president will make a move","h":"<article class=\"card\" id=\"sc-horikita-manabu-y1v5-p26-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-manabu.html#sc-horikita-manabu-y1v5-p26-1\">Ch.2: passing mention<\/a><\/span><span class=\"meta\">Y1V5 · p.26<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a><\/span><\/h3><p class=\"setup\">Named as the third-year Class A student and student council president Suzune is scanning for; he does not take Red Team command.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/index.html#fujimaki\">Fujimaki<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> She has never sought him out first — he always initiates contact — and cannot find him in the four-hundred-strong crowd.<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Fujimaki<\/b> Fujimaki’s command of the Red Team makes Ayanokōji wonder when the president will make a move.<span class=\"pg\">p.26<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-manabu-y1v5-p68-1\">→ After: Ch.5 §5: The brother, revealed to the group<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y1v5-p26-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"horikita-manabu katsuragi-kouhei ayanokouji-kiyotaka ryuuen-kakeru ichinose-honami horikita-suzune","q":"horikita suzune ch 2  2 2  the assembly and the coin in gymnasium 1 she scans restlessly for her brother  he never takes red team command  and fujimaki does instead  has never gone to meet him first   he always initiates contact   and cannot spot him in the crowd of four hundred  gets his warning about ryuuen and answers with a pointed question about personal experience  he leaves it at  i ve warned you  pulls him into the strategy question   what factor besides athleticism decides the festival   and gets  mere luck  for her trouble   i m not talking about random chance  though    wants a definite method  not luck  carries shame over her island mistakes  the narration reads her as even more obsessed with victory   different  i think it s the same kind of special exam    against ayanokoji s distinction   i definitely want class d to win    retort when he says she wants loopholes  not preparation   so  you re saying that we need to fight clean and fight hard to win   wait  are you saying that classes b and c are working together behind the scenes   but if that s true  it s crazy    can t believe ryuuen could have a plan already   fine  do enlighten me    swallows the rudeness and asks to be set straight  defends her b and c reading against his push  she thinks a behind the scenes deal is unlikely  suggests ichinose might set aside her feelings and cooperate with ryuuen for victory   ayanokoji calls the view too small","h":"<article class=\"card\" id=\"sc-horikita-suzune-y1v5-p26-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y1v5-p26-1\">Ch.2 §2.2: the assembly and the coin<\/a><\/span><span class=\"meta\">Y1V5 · p.26–34<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">In Gymnasium 1 she scans restlessly for her brother; he never takes Red Team command, and Fujimaki does instead.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “I’m not talking about random chance, though,” — wants a definite method, not luck.<span class=\"pg\">p.32<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Different? I think it’s the same kind of special exam.” — against Ayanokōji’s distinction.<span class=\"pg\">p.32<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “I definitely want Class D to win,” — retort when he says she wants loopholes, not preparation.<span class=\"pg\">p.33<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Has never gone to meet him first — he always initiates contact — and cannot spot him in the crowd of four hundred.<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Gets his warning about Ryuuen and answers with a pointed question about personal experience; he leaves it at “I’ve warned you.”<span class=\"pg\">p.28<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Pulls him into the strategy question — what factor besides athleticism decides the festival — and gets “Mere luck?” for her trouble.<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Carries shame over her island mistakes; the narration reads her as even more obsessed with victory.<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So, you’re saying that we need to fight clean and fight hard to win?”<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wait. Are you saying that Classes B and C are working together behind the scenes?”<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But if that’s true, it’s crazy.” — can’t believe Ryuuen could have a plan already.<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Fine, do enlighten me.” — swallows the rudeness and asks to be set straight.<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Defends her B-and-C reading against his push; she thinks a behind-the-scenes deal is unlikely.<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Suggests Ichinose might set aside her feelings and cooperate with Ryuuen for victory — Ayanokōji calls the view too small.<span class=\"pg\">p.34<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v5-p16-1\">← Before: Ch.2 §2.1: the briefing and the huddle<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v5-p39-1\">→ After: Ch.3 §3: Her plan wins the vote<\/button><\/div><\/article>"},{"i":"sc-katsuragi-kouhei-y1v5-p26-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"hirata-yousuke ryuuen-kakeru sakayanagi-arisu totsuka-yahiko katsuragi-kouhei","q":"katsuragi kohei ch 2  2 2  the class a face assembles the first year class a students in droves after fujimaki s speech and becomes the class s negotiating face at the red team meeting   i hope we can join forces without any problems  strikes the keep out of each other s way pact with hirata   no shared competition details  only a meeting to come for the group events   i was thinking that it d be best if we just keep out of each other s way   letting that information slip might lead to unnecessary conflict down the road   i ll consult with everyone else  warns horikita off him  he ll laugh while he attacks in the same instant   and leaves his own experience unspoken   don t underestimate ryuuen   i ve warned you  introduces sakayanagi by name and asks for sensitivity  watches her quietly while nearly all the class sits with her faction   that s sakayanagi arisu  yahiko is named among the few boys and girls sitting on his side of the line  the narration reads his faction as possibly no longer superior   sakayanagi may be demonstrating her power deliberately","h":"<article class=\"card\" id=\"sc-katsuragi-kouhei-y1v5-p26-1\"><h3><span class=\"ttl\"><a href=\"../../../people/katsuragi-kouhei.html#sc-katsuragi-kouhei-y1v5-p26-1\">Ch.2 §2.2: the Class A face<\/a><\/span><span class=\"meta\">Y1V5 · p.26–31<\/span><span class=\"by\">notes on <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/span><\/h3><p class=\"setup\">Assembles the first-year Class A students in droves after Fujimaki’s speech and becomes the class’s negotiating face at the Red Team meeting.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/totsuka-yahiko.html\">Totsuka Yahiko<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Katsuragi Kōhei<\/b> “I hope we can join forces without any problems,”<span class=\"pg\">p.27<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Katsuragi Kōhei<\/b> “I was thinking that it’d be best if we just keep out of each other’s way.”<span class=\"pg\">p.31<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Katsuragi Kōhei<\/b> “Letting that information slip might lead to unnecessary conflict down the road.”<span class=\"pg\">p.31<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Strikes the keep-out-of-each-other’s-way pact with Hirata — no shared competition details, only a meeting to come for the group events.<span class=\"pg\">p.27<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll consult with everyone else.”<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Warns Horikita off him: he’ll laugh while he attacks in the same instant — and leaves his own experience unspoken.<span class=\"pg\">p.28<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t underestimate Ryuuen.”<span class=\"pg\">p.28<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ve warned you.”<span class=\"pg\">p.28<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Introduces Sakayanagi by name and asks for sensitivity; watches her quietly while nearly all the class sits with her faction.<span class=\"pg\">p.28<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s Sakayanagi Arisu.”<span class=\"pg\">p.28<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Totsuka Yahiko<\/b> Yahiko is named among the few boys and girls sitting on his side of the line.<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Position<\/span> The narration reads his faction as possibly no longer superior — Sakayanagi may be demonstrating her power deliberately.<span class=\"pg\">p.30<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-katsuragi-kouhei-y1v5-p54-1\">→ After: Ch.4 §4: The standing Class A meetings<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y1v5-p27-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"ryuuen-kakeru ayanokouji-kiyotaka ichinose-honami","q":"ichinose honami ch 2  2 2  confronting the walkout interrupts katsuragi s briefing as almost her entire class s counterpart walks out   she questions ryuuen to his face   so  you don t intend to hold a discussion   i see  so  you re just saving us the hassle  then   you really think you can win without cooperating  gets gratitude for the trouble saved and his sneer as an answer  class c leaves anyway  ayanokoji later names her as the kind who might set feelings aside and cooperate with ryuuen for victory","h":"<article class=\"card\" id=\"sc-ichinose-honami-y1v5-p27-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y1v5-p27-1\">Ch.2 §2.2: confronting the walkout<\/a><\/span><span class=\"meta\">Y1V5 · p.27<\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><p class=\"setup\">Interrupts Katsuragi’s briefing as almost her entire class’s counterpart walks out — she questions Ryuuen to his face.<\/p><p class=\"with\">with <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “So, you don’t intend to hold a discussion?”<span class=\"pg\">p.27<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “I see. So, you’re just saving us the hassle, then,”<span class=\"pg\">p.27<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “You really think you can win without cooperating?”<span class=\"pg\">p.27<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Gets gratitude for the trouble saved and his sneer as an answer; Class C leaves anyway.<span class=\"pg\">p.27<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Ayanokōji later names her as the kind who might set feelings aside and cooperate with Ryuuen for victory.<span class=\"pg\">p.33<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ryuuen-kakeru-y1v5-p27-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"ichinose-honami manabe-shiho katsuragi-kouhei ayanokouji-kiyotaka ryuuen-kakeru","q":"ryuen kakeru ch 2  2 2  the walkout when ichinose asks why class c won t discuss strategy  he turns with his hands in his pockets and leads the whole class out of the gym   it s a waste of time   you should be grateful   hmm  i wonder    to ichinose s challenge on winning without cooperating  refuses her cooperation talk to her face  the exit confirms class c s dictatorship  manabe follows him out after the glance back at karuizawa  katsuragi s warning to horikita is keyed to him  he ll laugh while he attacks in the same instant  ayanokoji s read  always looking to win  possibly already holding one or more festival tactics behind the b and c refusal  the walkout confirms his hold on class c inside the volume s first pages","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y1v5-p27-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y1v5-p27-1\">Ch.2 §2.2: the walkout<\/a><\/span><span class=\"meta\">Y1V5 · p.27–28<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"setup\">When Ichinose asks why Class C won’t discuss strategy, he turns with his hands in his pockets and leads the whole class out of the gym.<\/p><p class=\"with\">with <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/manabe-shiho.html\">Manabe Shiho<\/a> · <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> “It’s a waste of time,”<span class=\"pg\">p.27<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> “You should be grateful.”<span class=\"pg\">p.27<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> “Hmm, I wonder.” — to Ichinose’s challenge on winning without cooperating.<span class=\"pg\">p.27<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Refuses her cooperation talk to her face; the exit confirms Class C’s dictatorship.<span class=\"pg\">p.27<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Manabe Shiho<\/b> Manabe follows him out after the glance-back at Karuizawa.<span class=\"pg\">p.28<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Katsuragi’s warning to Horikita is keyed to him: he’ll laugh while he attacks in the same instant.<span class=\"pg\">p.28<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Ayanokōji’s read: always looking to win, possibly already holding one or more festival tactics behind the B-and-C refusal.<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Position<\/span> The walkout confirms his hold on Class C inside the volume’s first pages.<span class=\"pg\">p.27<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y1v5-p54-1\">→ After: Ch.4 §4: The reconnaissance that isn’t<\/button><\/div><\/article>"},{"i":"sc-karuizawa-kei-y1v5-p28-1","v":"y1v5","y":1,"o":6,"k":"","w":"manabe-shiho karuizawa-kei","q":"karuizawa kei ch 2  2 2  the class c exit as class c files out of the gym  her expression sours for an instant at manabe s glance  manabe looks back at her from ryuuen s wake   the cruise ship scrap and bullying history   then averts her eyes and follows the class out","h":"<article class=\"card\" id=\"sc-karuizawa-kei-y1v5-p28-1\"><h3><span class=\"ttl\"><a href=\"../../../people/karuizawa-kei.html#sc-karuizawa-kei-y1v5-p28-1\">Ch.2 §2.2: the Class C exit<\/a><\/span><span class=\"meta\">Y1V5 · p.28<\/span><span class=\"by\">notes on <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/span><\/h3><p class=\"setup\">As Class C files out of the gym, her expression sours for an instant at Manabe’s glance.<\/p><p class=\"with\">with <a href=\"../../../people/manabe-shiho.html\">Manabe Shiho<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Manabe Shiho<\/b> Manabe looks back at her from Ryuuen’s wake — the cruise-ship scrap and bullying history — then averts her eyes and follows the class out.<span class=\"pg\">p.28<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-karuizawa-kei-y1v5-p13-1\">← Before: Ch.2: the zodiac debrief at Pallet<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-karuizawa-kei-y1v5-p39-1\">→ After: Ch.3 §3: The other camp, then the entrance meeting<\/button><\/div><\/article>"},{"i":"sc-manabe-shiho-y1v5-p28-1","v":"y1v5","y":1,"o":6,"k":"","w":"karuizawa-kei manabe-shiho","q":"manabe shiho ch 2  passing mention as class c leaves the gym  manabe looks back at karuizawa for a moment  averts her eyes  and follows ryuuen out  the glance reopens the cruise ship scrap where karuizawa s bullying history surfaced","h":"<article class=\"card\" id=\"sc-manabe-shiho-y1v5-p28-1\"><h3><span class=\"ttl\"><a href=\"../../../people/manabe-shiho.html#sc-manabe-shiho-y1v5-p28-1\">Ch.2: passing mention<\/a><\/span><span class=\"meta\">Y1V5 · p.28<\/span><span class=\"by\">notes on <a href=\"../../../people/manabe-shiho.html\">Manabe Shiho<\/a><\/span><\/h3><p class=\"setup\">As Class C leaves the gym, Manabe looks back at Karuizawa for a moment, averts her eyes, and follows Ryuuen out.<\/p><p class=\"with\">with <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> The glance reopens the cruise-ship scrap where Karuizawa’s bullying history surfaced.<span class=\"pg\">p.28<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-sakayanagi-arisu-y1v5-p28-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"katsuragi-kouhei hirata-yousuke sakayanagi-arisu","q":"sakayanagi arisu ch 2  2 2  the introduction first full appearance  the petite girl alone with a thin cane  introduced by katsuragi as disabled   class a s other rumored leader   unfortunately  i won t be very useful in this competition   your kindness overwhelms me    to the class d boys who rush to reassure her  the class s line is clear between his followers and hers  nearly all the students sit with her   perhaps a deliberate demonstration  hirata reassures her when she apologizes for being consistently absent  short silver hair  pale skin  a dreamlike quality that makes people instinctively want to protect her   and a strength of will behind the weakness  did not participate in the island or cruise ship tests  whether a penalty was incurred is left open by the page","h":"<article class=\"card\" id=\"sc-sakayanagi-arisu-y1v5-p28-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakayanagi-arisu.html#sc-sakayanagi-arisu-y1v5-p28-1\">Ch.2 §2.2: the introduction<\/a><\/span><span class=\"meta\">Y1V5 · p.28–31<\/span><span class=\"by\">notes on <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/span><\/h3><p class=\"setup\">First full appearance: the petite girl alone with a thin cane, introduced by Katsuragi as disabled — Class A’s other rumored leader.<\/p><p class=\"with\">with <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “Unfortunately, I won’t be very useful in this competition.”<span class=\"pg\">p.30<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “Your kindness overwhelms me,” — to the Class D boys who rush to reassure her.<span class=\"pg\">p.30<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> The class’s line is clear between his followers and hers; nearly all the students sit with her — perhaps a deliberate demonstration.<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Hirata reassures her when she apologizes for being consistently absent.<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Short silver hair, pale skin, a dreamlike quality that makes people instinctively want to protect her — and a strength of will behind the weakness.<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Position<\/span> Did not participate in the island or cruise ship tests; whether a penalty was incurred is left open by the page.<span class=\"pg\">p.31<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y1v5-p68-1\">→ After: Ch.5 §5: Rumored from a distance<\/button><\/div><\/article>"},{"i":"sc-sakura-airi-y1v5-p30-1","v":"y1v5","y":1,"o":6,"k":"","w":"sakayanagi-arisu sakura-airi","q":"sakura airi ch 2  passing mention named in the narration comparing sakayanagi s looks to kushida and her  one of the two girls sakayanagi is measured against when class d s boys size her up","h":"<article class=\"card\" id=\"sc-sakura-airi-y1v5-p30-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakura-airi.html#sc-sakura-airi-y1v5-p30-1\">Ch.2: passing mention<\/a><\/span><span class=\"meta\">Y1V5 · p.30<\/span><span class=\"by\">notes on <a href=\"../../../people/sakura-airi.html\">Sakura Airi<\/a><\/span><\/h3><p class=\"setup\">Named in the narration comparing Sakayanagi’s looks to Kushida and her.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> One of the two girls Sakayanagi is measured against when Class D’s boys size her up.<span class=\"pg\">p.30<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakura-airi-y1v5-p39-1\">→ After: Ch.3 §3: Follows Sudou’s hand<\/button><\/div><\/article>"},{"i":"sc-totsuka-yahiko-y1v5-p30-1","v":"y1v5","y":1,"o":6,"k":"","w":"katsuragi-kouhei totsuka-yahiko","q":"totsuka yahiko ch 2  passing mention named among the boys sitting with katsuragi s faction in the class a split  one of the few class a students counted on katsuragi s side of the line","h":"<article class=\"card\" id=\"sc-totsuka-yahiko-y1v5-p30-1\"><h3><span class=\"ttl\"><a href=\"../../../people/totsuka-yahiko.html#sc-totsuka-yahiko-y1v5-p30-1\">Ch.2: passing mention<\/a><\/span><span class=\"meta\">Y1V5 · p.30<\/span><span class=\"by\">notes on <a href=\"../../../people/totsuka-yahiko.html\">Totsuka Yahiko<\/a><\/span><\/h3><p class=\"setup\">Named among the boys sitting with Katsuragi’s faction in the Class A split.<\/p><p class=\"with\">with <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> One of the few Class A students counted on Katsuragi’s side of the line.<span class=\"pg\">p.30<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y1v5-p35-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"chabashira-sae ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 2  2 3  the gate after class he stays behind alone with a file on his phone   whatever it showed  he decides no traps are necessary   then runs into chabashira spraying water at the main gate   are you on duty today   don t you think that s an exaggeration   no  nothing like that    to chabashira s guess that he already has an eccentric strategy in place   i m free to decide my own path  she warns that if he shows no results soon she ll stop covering for him  the confrontation was only a matter of time  blank short scan page inside the dialogue  footer and watermark only  p 38 is likewise a blank scan","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v5-p35-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v5-p35-1\">Ch.2 §2.3: the gate<\/a><\/span><span class=\"meta\">Y1V5 · p.35–38<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">After class he stays behind alone with a file on his phone — whatever it showed, he decides no traps are necessary — then runs into Chabashira spraying water at the main gate.<\/p><p class=\"with\">with <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Are you on duty today?”<span class=\"pg\">p.35<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Don’t you think that’s an exaggeration?”<span class=\"pg\">p.37<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “No, nothing like that,” — to Chabashira’s guess that he already has an eccentric strategy in place.<span class=\"pg\">p.37<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I’m free to decide my own path.”<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Chabashira Sae<\/b> She warns that if he shows no results soon she’ll stop covering for him; the confrontation was only a matter of time.<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Blank/short scan page inside the dialogue (footer and watermark only); p.38 is likewise a blank scan.<span class=\"pg\">p.36<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v5-p26-1\">← Before: Ch.2 §2.2: the Red Team assembly<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v5-p39-1\">→ After: Ch.3 §3: The blackboard vote, the betrayal warning, the roster<\/button><\/div><\/article>"},{"i":"sc-chabashira-sae-y1v5-p35-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"ayanokouji-kiyotaka chabashira-sae","q":"chabashira sae ch 2  2 3  the gate spraying water at the main gate after school  she s on duty and clocks that he stayed behind later than usual   you stayed behind longer than usual  ayanokouji   are you prepared for the sports festival   in your case  i would have thought that you d already have some eccentric idea or strategy in place   but if you don t show me some results soon  i ll stop covering for you  their talk stops when their eyes meet   public discussion helps no one  she accepts his right to choose his path but puts a deadline on her cover  blank short scan page sits inside the dialogue  footer and watermark only","h":"<article class=\"card\" id=\"sc-chabashira-sae-y1v5-p35-1\"><h3><span class=\"ttl\"><a href=\"../../../people/chabashira-sae.html#sc-chabashira-sae-y1v5-p35-1\">Ch.2 §2.3: the gate<\/a><\/span><span class=\"meta\">Y1V5 · p.35–37<\/span><span class=\"by\">notes on <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a><\/span><\/h3><p class=\"setup\">Spraying water at the main gate after school; she’s on duty and clocks that he stayed behind later than usual.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Chabashira Sae<\/b> “You stayed behind longer than usual, Ayanokouji.”<span class=\"pg\">p.35<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Chabashira Sae<\/b> “Are you prepared for the sports festival?”<span class=\"pg\">p.37<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Chabashira Sae<\/b> “In your case, I would have thought that you’d already have some eccentric idea or strategy in place,”<span class=\"pg\">p.37<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “But if you don’t show me some results soon, I’ll stop covering for you.”<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Their talk stops when their eyes meet — public discussion helps no one; she accepts his right to choose his path but puts a deadline on her cover.<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Blank/short scan page sits inside the dialogue (footer and watermark only).<span class=\"pg\">p.36<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-chabashira-sae-y1v5-p16-1\">← Before: Ch.2 §2.1: the sports festival briefing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-chabashira-sae-y1v5-p39-1\">→ After: Ch.3 §3: Watches the homeroom from the back<\/button><\/div><\/article>"},{"i":"sc-sports-festival-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"","w":"","q":"sports festival ch 3  3  four way tug of war and the luck events the four way tug of war takes four people from each of the four classes   sixteen in all   who pull simultaneously  so tactics matter beyond raw strength  luck based events such as the scavenger hunt are staffed by rock paper scissors among the volunteers  on hirata s call   simple is best  how about we go with rock paper scissors  class d s roster fills only about a third of the all participant spots at the first pass  the rest stay open for later practice","h":"<article class=\"card\" id=\"sc-sports-festival-y1v5-p39-1\"><h3><span class=\"ttl\"><a href=\"../../../school/exam/sports-festival.html#sc-sports-festival-y1v5-p39-1\">Ch.3 §3: Four-way tug-of-war and the luck events<\/a><\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><span class=\"by\">notes on <a href=\"../../../school/exam/sports-festival.html\">Sports Festival<\/a><\/span><\/h3><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Rule<\/span> The four-way tug-of-war takes four people from each of the four classes — sixteen in all — who pull simultaneously, so tactics matter beyond raw strength.<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> Luck-based events such as the scavenger hunt are staffed by rock-paper-scissors among the volunteers, on Hirata’s call: “Simple is best. How about we go with rock-paper-scissors?”<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Scope<\/span> Class D’s roster fills only about a third of the all-participant spots at the first pass; the rest stay open for later practice.<span class=\"pg\">p.44<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sports-festival-y1v5-p26-1\">← Before: Ch.2 §2.2: the assembly<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"action inner spoken","w":"horikita-suzune ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 3  3  the blackboard vote  the betrayal warning  the roster class 1 d homeroom  hirata chalks two systems for the sports festival while ayanokoji narrates the class s first real strategy meeting of the volume   we began making comprehensive preparations for the sports festival  which was only one month away  lets horikita s jab about his phone pass  then stays out of the debate   well  if i just leave it to you and hirata  you ll sort out our problems  right   relax  it s my policy to abstain from voting   the other students aren t all as ambitious as you    he votes for no one while the class splits 16 13  after class he texts karuizawa    no matter what  object to horikita s plan  then ask kushida for her opinion    and meets her at the main entrance   when it comes to improvising  you re quite fast on your feet   besides  i m under no compunction to answer your questions   i m not personally interested in reaching class a  tells karuizawa   one of our classmates will betray us during this sports festival   yes  i ve prepared   now then  i wonder what class a has in mind    katsuragi will be solid  and sakayanagi would be good for the white team and for class d  life jacket parable  in a crisis the able bodied are favored  so  just because sakayanagi wasn t physically active didn t mean she was harmless   karuizawa was better at reading people than i d imagined  probably because of her past  measures 60 6 kilograms of grip strength on the first try   second in the class behind sudou s 82 4  with koenji set aside   having aimed carefully at the average  stops the meter just over 60 once he has worked out that 60 is roughly the average he was aiming for   i see  so  60 was high  then  wins the first round and the second and final round of rock paper scissors despite praying to lose  and is picked for the scavenger hunt team against his wishes  admits the roster problem    many participants were chosen against their will    and horikita answers that the class s athletic gap is to blame","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v5-p39-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v5-p39-1\">Ch.3 §3: The blackboard vote, the betrayal warning, the roster<\/a><\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Class 1-D homeroom: Hirata chalks two systems for the sports festival while Ayanokōji narrates the class’s first real strategy meeting of the volume.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Relax. It’s my policy to abstain from voting.”<span class=\"pg\">p.43<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “The other students aren’t all as ambitious as you,” — he votes for no one while the class splits 16–13.<span class=\"pg\">p.43<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “When it comes to improvising, you’re quite fast on your feet.”<span class=\"pg\">p.46<\/span><\/li><\/ul><details class=\"more\"><summary>15 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Inner voice<\/span> “We began making comprehensive preparations for the sports festival, which was only one month away.”<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Lets Horikita’s jab about his phone pass, then stays out of the debate: “Well, if I just leave it to you and Hirata, you’ll sort out our problems, right?”<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> After class he texts Karuizawa — “No matter what, object to Horikita’s plan. Then ask Kushida for her opinion.” — and meets her at the main entrance.<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Besides, I’m under no compunction to answer your questions.”<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m not personally interested in reaching Class A.”<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Unverified<\/span> Tells Karuizawa: “One of our classmates will betray us during this sports festival.”<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes. I’ve prepared.”<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> “Now then, I wonder what Class A has in mind?” — Katsuragi will be solid, and Sakayanagi would be good for the White Team and for Class D.<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> Life-jacket parable: in a crisis the able-bodied are favored, so “just because Sakayanagi wasn’t physically active didn’t mean she was harmless.”<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> “Karuizawa was better at reading people than I’d imagined, probably because of her past.”<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Measures 60.6 kilograms of grip strength on the first try — second in the class behind Sudou’s 82.4, with Kōenji set aside — having aimed carefully at the average.<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> Stops the meter just over 60 once he has worked out that 60 is roughly the average he was aiming for.<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> “I see. So, 60 was high, then.”<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Wins the first round and the second and final round of rock-paper-scissors despite praying to lose, and is picked for the scavenger-hunt team against his wishes.<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Admits the roster problem — “Many participants were chosen against their will,” — and Horikita answers that the class’s athletic gap is to blame.<span class=\"pg\">p.52<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v5-p35-1\">← Before: Ch.2 §2.3: the gate<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v5-p54-1\">→ After: Ch.4 §4: The Ryuuen read, the partner lesson, the two problems<\/button><\/div><\/article>"},{"i":"sc-chabashira-sae-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"","w":"hirata-yousuke chabashira-sae","q":"chabashira sae ch 3  3  watches the homeroom from the back chabashira moves to the back of the classroom during hirata s two hour homeroom and does not speak   she intends to watch the class run itself  lets hirata run the session unopposed   she speaks no word during the whole strategy meeting  the chapter prints nothing further about her  her last stated posture is watching from the back  p 39","h":"<article class=\"card\" id=\"sc-chabashira-sae-y1v5-p39-1\"><h3><span class=\"ttl\"><a href=\"../../../people/chabashira-sae.html#sc-chabashira-sae-y1v5-p39-1\">Ch.3 §3: Watches the homeroom from the back<\/a><\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><span class=\"by\">notes on <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a><\/span><\/h3><p class=\"setup\">Chabashira moves to the back of the classroom during Hirata’s two-hour homeroom and does not speak — she intends to watch the class run itself.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Lets Hirata run the session unopposed — she speaks no word during the whole strategy meeting.<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The chapter prints nothing further about her; her last stated posture is watching from the back (p.39).<span class=\"pg\">p.41<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-chabashira-sae-y1v5-p35-1\">← Before: Ch.2 §2.3: the gate<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"action spoken","w":"karuizawa-kei kouenji-rokusuke sotomura-hideo ayanokouji-kiyotaka hirata-yousuke","q":"hirata yosuke ch 3  3  runs the homeroom  the vote and the roster hirata takes the two hour homeroom in hand while chabashira watches from the back  chalks two systems on the board  and walks the class through them   this is a rough outline  but i think that everything boils down to these two approaches   the strength of the raising hands system is  naturally  that everyone gets to voice their wishes  calls the majority vote when the two camps can t agree   if we can t agree  then we ve got to have a majority vote   calm down  both of you  karuizawa accepts the vote mechanism at once    if yousuke kun says so  then i agree   how about we decide which plan we prefer by a show of hands   sixteen votes  then  defuses sudou s confrontation with koenji   kouenji kun must have his reasons   i think that it would be best to take our time with the rest  opens the grip strength testing    how about we measure the grip strength of our dominant hand    and records the results for the tug of war orders  sets the four way tug of war order by grip strength  sudou  ayanokoji  miyake and himself  explains the four way tug of war after looking it up    it s a tug of war competition in which four people are chosen from each of the four classes  for a total of sixteen people   how about we go with rock paper scissors  names the scavenger hunt five    ayanokouji kun  yukimura kun  sotomura kun  mori san  and maezono san    then fills every roster   this information is top secret  so everyone  please only make note of your events and your partners","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y1v5-p39-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y1v5-p39-1\">Ch.3 §3: Runs the homeroom, the vote and the roster<\/a><\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">Hirata takes the two-hour homeroom in hand while Chabashira watches from the back, chalks two systems on the board, and walks the class through them.<\/p><p class=\"with\">with <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a> · <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"../../../people/sotomura-hideo.html\">Sotomura Hideo<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “This is a rough outline, but I think that everything boils down to these two approaches.”<span class=\"pg\">p.39<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “The strength of the raising-hands system is, naturally, that everyone gets to voice their wishes.”<span class=\"pg\">p.39<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “Calm down, both of you.”<span class=\"pg\">p.42<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> Calls the majority vote when the two camps can’t agree: “If we can’t agree, then we’ve got to have a majority vote.”<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Karuizawa accepts the vote mechanism at once — “If Yousuke-kun says so, then I agree.”<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How about we decide which plan we prefer by a show of hands?”<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sixteen votes, then.”<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Defuses Sudou’s confrontation with Kōenji: “Kouenji-kun must have his reasons.”<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I think that it would be best to take our time with the rest.”<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Opens the grip-strength testing — “How about we measure the grip strength of our dominant hand?” — and records the results for the tug-of-war orders.<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Sets the four-way tug-of-war order by grip strength: Sudou, Ayanokōji, Miyake and himself.<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sotomura Hideo<\/b> Explains the four-way tug-of-war after looking it up — “It’s a tug-of-war competition in which four people are chosen from each of the four classes, for a total of sixteen people.”<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How about we go with rock-paper-scissors?”<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Names the scavenger-hunt five — “Ayanokouji-kun, Yukimura-kun, Sotomura-kun, Mori-san, and Maezono-san.” — then fills every roster.<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This information is top secret, so everyone, please only make note of your events and your partners.”<span class=\"pg\">p.52<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v5-p26-1\">← Before: Ch.2 §2.2: the assembly<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v5-p54-1\">→ After: Ch.4 §4: Gentle methods, three-legged partner<\/button><\/div><\/article>"},{"i":"sc-hondou-ryoutaro-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"","w":"hirata-yousuke hondou-ryoutaro","q":"hondo ryotaro ch 3  3  grip strength testing hirata hands hondou one of the two grip strength devices to run the measurement line  stands at hirata s right as a device holder  alongside yukimura  before sudou snatches the other one","h":"<article class=\"card\" id=\"sc-hondou-ryoutaro-y1v5-p39-1\"><h3><span class=\"ttl\">Ch.3 §3: Grip-strength testing<\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#hondou-ryoutaro\">Hondō Ryōtaro<\/a><\/span><\/h3><p class=\"setup\">Hirata hands Hondou one of the two grip-strength devices to run the measurement line.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Stands at Hirata’s right as a device holder, alongside Yukimura, before Sudou snatches the other one.<span class=\"pg\">p.49<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-horikita-suzune-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"action spoken","w":"shinohara-satsuki sudou-ken karuizawa-kei ayanokouji-kiyotaka horikita-suzune","q":"horikita suzune ch 3  3  her plan wins the vote horikita cuts into hirata s homeroom with a supplementary proposal while sudou is claiming every recommended event   however  that single tactic isn t guaranteed to carry us to victory   put simply  the strongest  fastest students should be grouped together  tells shinohara her feelings don t matter   it s for the sake of the class  tells her   besides  you probably wouldn t win anything anyway   i don t want to hear your excuses anymore  her compromise  top placers who don t need test points share private points with the bottom    the entire class will share in the gains and losses of private points from the festival  grumbled at karuizawa s side of the room   the other class definitely isn t weighed down by morons like you  closes her appeal   i hope you ll all make the right decision  asks ayanokoji to silence karuizawa    ayanokouji kun  can t you tell karuizawa san to shut up    and gets a refusal  accuses him   you ve been talking to her lately  though  turns on him   don t tell me you agree with karuizawa san s plan  growls back   in that case  you could just have voted for my plan  defends her plan   giving the class the best possible chance of winning will ultimately result in netting a lot of private points  her plan takes sixteen of the twenty nine votes cast  karuizawa s takes thirteen    then it s decided  she says  and hands the rest to hirata  volunteers herself   i will also compete in as many events as possible  notes his mood after the roster is filled    you look more somber than usual    and blames the class s athletic gap","h":"<article class=\"card\" id=\"sc-horikita-suzune-y1v5-p39-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y1v5-p39-1\">Ch.3 §3: Her plan wins the vote<\/a><\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">Horikita cuts into Hirata’s homeroom with a supplementary proposal while Sudou is claiming every recommended event.<\/p><p class=\"with\">with <a href=\"../../../people/shinohara-satsuki.html\">Shinohara Satsuki<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a> · <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “However, that single tactic isn’t guaranteed to carry us to victory,”<span class=\"pg\">p.40<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Put simply, the strongest, fastest students should be grouped together,”<span class=\"pg\">p.40<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “I don’t want to hear your excuses anymore.”<span class=\"pg\">p.41<\/span><\/li><\/ul><details class=\"more\"><summary>13 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shinohara Satsuki<\/b> Tells Shinohara her feelings don’t matter: “It’s for the sake of the class,”<span class=\"pg\">p.40<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shinohara Satsuki<\/b> Tells her: “Besides, you probably wouldn’t win anything anyway.”<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Her compromise: top placers who don’t need test points share private points with the bottom — “The entire class will share in the gains and losses of private points from the festival.”<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Grumbled at Karuizawa’s side of the room: “The other class definitely isn’t weighed down by morons like you,”<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Closes her appeal: “I hope you’ll all make the right decision,”<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Asks Ayanokōji to silence Karuizawa — “Ayanokouji-kun, can’t you tell Karuizawa-san to shut up?” — and gets a refusal.<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Accuses him: “You’ve been talking to her lately, though.”<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Turns on him: “Don’t tell me you agree with Karuizawa-san’s plan?”<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Growls back: “In that case, you could just have voted for my plan,”<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> Defends her plan: “Giving the class the best-possible chance of winning will ultimately result in netting a lot of private points.”<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Result<\/span> Her plan takes sixteen of the twenty-nine votes cast; Karuizawa’s takes thirteen — “Then it’s decided,” she says, and hands the rest to Hirata.<span class=\"pg\">p.43–44<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Volunteers herself: “I will also compete in as many events as possible.”<span class=\"pg\">p.44<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Notes his mood after the roster is filled — “You look more somber than usual.” — and blames the class’s athletic gap.<span class=\"pg\">p.52<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v5-p26-1\">← Before: Ch.2 §2.2: the assembly and the coin<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v5-p54-1\">→ After: Ch.4 §4: The name bet and the partner problem<\/button><\/div><\/article>"},{"i":"sc-ike-kanji-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"hirata-yousuke sotomura-hideo ike-kanji","q":"ike kanji ch 3  3  grip strength and the scavenger hunt ike takes his turn at the grip strength meter and pleads for bonus points on his score   i got a 42 6  begs hirata to round 42 6 up to 50    can you give me a few tiny bonus points and make it 50  asks whether the luck events are closed   hey  hirata  are we not getting any more chances to enter events  asks hirata   so  how are we going to decide that    when hirata says the scavenger hunt is decided by luck   i m so jealous    after ayanokoji s group is picked for the scavenger hunt","h":"<article class=\"card\" id=\"sc-ike-kanji-y1v5-p39-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ike-kanji.html#sc-ike-kanji-y1v5-p39-1\">Ch.3 §3: Grip strength and the scavenger hunt<\/a><\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><span class=\"by\">notes on <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a><\/span><\/h3><p class=\"setup\">Ike takes his turn at the grip-strength meter and pleads for bonus points on his score.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/sotomura-hideo.html\">Sotomura Hideo<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ike Kanji<\/b> “I got a 42.6.”<span class=\"pg\">p.50<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Begs Hirata to round 42.6 up to 50 — “Can you give me a few tiny bonus points and make it 50?”<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Asks whether the luck events are closed: “Hey, Hirata, are we not getting any more chances to enter events?”<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Asks Hirata: “So, how are we going to decide that?” — when Hirata says the scavenger hunt is decided by luck.<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sotomura Hideo<\/b> “I’m so jealous!” — after Ayanokōji’s group is picked for the scavenger hunt.<span class=\"pg\">p.52<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ike-kanji-y1v5-p17-1\">← Before: Ch.2: the briefing and the huddle<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ike-kanji-y1v5-p54-1\">→ After: Ch.4 §4: The watching classes and the tug demo<\/button><\/div><\/article>"},{"i":"sc-karuizawa-kei-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"horikita-suzune hirata-yousuke ayanokouji-kiyotaka karuizawa-kei","q":"karuizawa kei ch 3  3  the other camp  then the entrance meeting karuizawa raises the unathletic students  objection in homeroom and  after class  waits at the main entrance for ayanokoji   hey  excuse me  i object to this  too   hey  what do you think  kushida san   we re still losing out on chances to win the big prize  horikita answers her   you re objecting just because she objected  that s completely illogical  insists on fairness   we have to make these competitions fair  then yields to hirata s vote  her plan takes thirteen votes against horikita s sixteen   the minority side of the class s first festival vote  shows him the text    no matter what  object to horikita s plan  then ask kushida for her opinion    and demands to know what he is playing at   so  i should just do as i m told  like a loyal dog  and never ask why  hears the betrayal prediction    wait  what  are you being serious right now  asks for reassurance   even if someone does betray the class  we ll be okay  right  her reading of people is praised in his thoughts after she leaves   better than he imagined  from her past","h":"<article class=\"card\" id=\"sc-karuizawa-kei-y1v5-p39-1\"><h3><span class=\"ttl\"><a href=\"../../../people/karuizawa-kei.html#sc-karuizawa-kei-y1v5-p39-1\">Ch.3 §3: The other camp, then the entrance meeting<\/a><\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><span class=\"by\">notes on <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/span><\/h3><p class=\"setup\">Karuizawa raises the unathletic students’ objection in homeroom and, after class, waits at the main entrance for Ayanokōji.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> “Hey, excuse me? I object to this, too.”<span class=\"pg\">p.41<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> “Hey, what do you think, Kushida-san?”<span class=\"pg\">p.41<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> “We’re still losing out on chances to win the big prize.”<span class=\"pg\">p.42<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Horikita answers her: “You’re objecting just because she objected? That’s completely illogical.”<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Insists on fairness: “We have to make these competitions fair,” then yields to Hirata’s vote.<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Result<\/span> Her plan takes thirteen votes against Horikita’s sixteen — the minority side of the class’s first festival vote.<span class=\"pg\">p.44<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Shows him the text — “No matter what, object to Horikita’s plan. Then ask Kushida for her opinion.” — and demands to know what he is playing at.<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So, I should just do as I’m told, like a loyal dog, and never ask why.”<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Hears the betrayal prediction — “Wait, what?! Are you being serious right now?!”<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Asks for reassurance: “even if someone does betray the class, we’ll be okay. Right?”<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Her reading of people is praised in his thoughts after she leaves — better than he imagined, from her past.<span class=\"pg\">p.48<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-karuizawa-kei-y1v5-p28-1\">← Before: Ch.2 §2.2: the Class C exit<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-karuizawa-kei-y1v5-p68-1\">→ After: Ch.5 §5: Named in passing<\/button><\/div><\/article>"},{"i":"sc-kouenji-rokusuke-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"hirata-yousuke sudou-ken kouenji-rokusuke","q":"koenji rokusuke ch 3  3  refuses to cooperate sudou confronts koenji over his abstention in the homeroom vote  koenji refuses to join the festival plan   i have no interest in this   i have no reason to let you bully me into anything  hirata ends the standoff    kouenji kun must have his reasons  ignores sudou s taunts at the meter    i ll pass  ignore me    polishing his fingernails instead  refuses the grip strength meter when sudou challenges him  ayanokoji later writes  kouenji aside  i ended up placing second in the class  so koenji ranked above without a printed figure","h":"<article class=\"card\" id=\"sc-kouenji-rokusuke-y1v5-p39-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kouenji-rokusuke.html#sc-kouenji-rokusuke-y1v5-p39-1\">Ch.3 §3: Refuses to cooperate<\/a><\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><span class=\"by\">notes on <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/span><\/h3><p class=\"setup\">Sudou confronts Kōenji over his abstention in the homeroom vote; Kōenji refuses to join the festival plan.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> “I have no interest in this.”<span class=\"pg\">p.45<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> “I have no reason to let you bully me into anything,”<span class=\"pg\">p.45<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Hirata ends the standoff — “Kouenji-kun must have his reasons.”<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Ignores Sudou’s taunts at the meter — “I’ll pass. Ignore me.” — polishing his fingernails instead.<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Refuses the grip-strength meter when Sudou challenges him; Ayanokōji later writes “Kouenji aside, I ended up placing second in the class,” so Kōenji ranked above without a printed figure.<span class=\"pg\">p.49–51<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y1v5-p54-1\">→ After: Ch.4 §4: Sits out the tests<\/button><\/div><\/article>"},{"i":"sc-kushida-kikyou-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"action spoken","w":"horikita-suzune kushida-kikyou","q":"kushida kikyo ch 3  3  asked for the middle ground karuizawa calls on kushida during the homeroom debate  and kushida voices the class s wish for a solution both sides can accept   if there were some kind of middle ground solution  that would be ideal   a strategy we could all get behind  names both camps fairly   horikita s wish for the class and shinohara s wish for everyone to have a chance   before horikita offers the compromise  volunteers for recommended events once horikita s plan carries the vote","h":"<article class=\"card\" id=\"sc-kushida-kikyou-y1v5-p39-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kushida-kikyou.html#sc-kushida-kikyou-y1v5-p39-1\">Ch.3 §3: Asked for the middle ground<\/a><\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><span class=\"by\">notes on <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a><\/span><\/h3><p class=\"setup\">Karuizawa calls on Kushida during the homeroom debate, and Kushida voices the class’s wish for a solution both sides can accept.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kushida Kikyō<\/b> “If there were some kind of middle-ground solution, that would be ideal.”<span class=\"pg\">p.41<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kushida Kikyō<\/b> “A strategy we could all get behind.”<span class=\"pg\">p.41<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Names both camps fairly — Horikita’s wish for the class and Shinohara’s wish for everyone to have a chance — before Horikita offers the compromise.<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Volunteers for recommended events once Horikita’s plan carries the vote.<span class=\"pg\">p.44<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kushida-kikyou-y1v5-p13-1\">← Before: Ch.2: passing mentions<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kushida-kikyou-y1v5-p54-1\">→ After: Ch.4 §4: Names Sudou the leader; named the second problem<\/button><\/div><\/article>"},{"i":"sc-maezono-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"","w":"hirata-yousuke maezono","q":"maezono ch 3  3  on the scavenger hunt roster maezono is named by hirata as one of the five picked for the scavenger hunt after the rock paper scissors  picked into the group    ayanokouji kun  yukimura kun  sotomura kun  mori san  and maezono san","h":"<article class=\"card\" id=\"sc-maezono-y1v5-p39-1\"><h3><span class=\"ttl\">Ch.3 §3: On the scavenger-hunt roster<\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#maezono\">Maezono<\/a><\/span><\/h3><p class=\"setup\">Maezono is named by Hirata as one of the five picked for the scavenger hunt after the rock-paper-scissors.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Picked into the group — “Ayanokouji-kun, Yukimura-kun, Sotomura-kun, Mori-san, and Maezono-san.”<span class=\"pg\">p.52<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-miyake-akito-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"","w":"hirata-yousuke miyake-akito","q":"miyake akito ch 3  3  grip strength and the tug of war order miyake is named in the four way tug of war order that hirata sets by grip strength  takes the third tug of war slot behind sudou and ayanokoji   sudou kun  ayanokouji kun  miyake kun  and me","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v5-p39-1\"><h3><span class=\"ttl\">Ch.3 §3: Grip strength and the tug-of-war order<\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#miyake-akito\">Miyake Akito<\/a><\/span><\/h3><p class=\"setup\">Miyake is named in the four-way tug-of-war order that Hirata sets by grip strength.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Takes the third tug-of-war slot behind Sudou and Ayanokōji: “Sudou-kun, Ayanokouji-kun, Miyake-kun, and me.”<span class=\"pg\">p.51<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-miyamoto-soshi-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"","w":"miyamoto-soshi","q":"miyamoto soshi ch 3  3  grip strength and the tug of war order miyamoto s grip strength is recorded at 48 kilograms during the boys  testing  measures 48 kilograms  between hirata s 57 9 and ike s 42 6  not among the four named for the four way tug of war   hirata s order is sudou  ayanokoji  miyake and himself","h":"<article class=\"card\" id=\"sc-miyamoto-soshi-y1v5-p39-1\"><h3><span class=\"ttl\">Ch.3 §3: Grip strength and the tug-of-war order<\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#miyamoto-soshi\">Miyamoto Soshi<\/a><\/span><\/h3><p class=\"setup\">Miyamoto’s grip strength is recorded at 48 kilograms during the boys’ testing.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Feat<\/span> Measures 48 kilograms, between Hirata’s 57.9 and Ike’s 42.6.<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Not among the four named for the four-way tug-of-war — Hirata’s order is Sudou, Ayanokōji, Miyake and himself.<span class=\"pg\">p.51<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-mori-nene-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"","w":"hirata-yousuke mori-nene","q":"mori nene ch 3  3  on the scavenger hunt roster mori is named by hirata as one of the five picked for the scavenger hunt after the rock paper scissors  picked into the group    ayanokouji kun  yukimura kun  sotomura kun  mori san  and maezono san","h":"<article class=\"card\" id=\"sc-mori-nene-y1v5-p39-1\"><h3><span class=\"ttl\">Ch.3 §3: On the scavenger-hunt roster<\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#mori-nene\">Mori Nene<\/a><\/span><\/h3><p class=\"setup\">Mori is named by Hirata as one of the five picked for the scavenger hunt after the rock-paper-scissors.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Picked into the group — “Ayanokouji-kun, Yukimura-kun, Sotomura-kun, Mori-san, and Maezono-san.”<span class=\"pg\">p.52<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-onodera-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"action","w":"onodera","q":"onodera ch 3  3  volunteers for the recommended events onodera is named with kushida among the students who volunteer for recommended competitions after horikita s plan carries the vote  offers herself for the recommended participant events once the class resolves to win as a class","h":"<article class=\"card\" id=\"sc-onodera-y1v5-p39-1\"><h3><span class=\"ttl\">Ch.3 §3: Volunteers for the recommended events<\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#onodera\">Onodera<\/a><\/span><\/h3><p class=\"setup\">Onodera is named with Kushida among the students who volunteer for recommended competitions after Horikita’s plan carries the vote.<\/p><ul class=\"lines\"><li class=\"q action\">Offers herself for the recommended-participant events once the class resolves to win as a class.<span class=\"pg\">p.44<\/span><\/li><\/ul><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-onodera-y1v5-p54-1\">→ After: Ch.4 §4: Three-legged partner for Horikita<\/button><\/div><\/article>"},{"i":"sc-sakura-airi-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"action","w":"sudou-ken sakura-airi","q":"sakura airi ch 3  3  follows sudou s hand sakura raises her hand with sudou and yukimura for horikita s ability plan during the homeroom vote  votes with the ability camp   one of the sixteen hands for horikita s plan  follows sudou s declared choice into the same camp","h":"<article class=\"card\" id=\"sc-sakura-airi-y1v5-p39-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakura-airi.html#sc-sakura-airi-y1v5-p39-1\">Ch.3 §3: Follows Sudou’s hand<\/a><\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><span class=\"by\">notes on <a href=\"../../../people/sakura-airi.html\">Sakura Airi<\/a><\/span><\/h3><p class=\"setup\">Sakura raises her hand with Sudou and Yukimura for Horikita’s ability plan during the homeroom vote.<\/p><p class=\"with\">with <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/p><ul class=\"lines\"><li class=\"q action\">Votes with the ability camp — one of the sixteen hands for Horikita’s plan.<span class=\"pg\">p.43<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Follows Sudou’s declared choice into the same camp.<span class=\"pg\">p.43<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakura-airi-y1v5-p30-1\">← Before: Ch.2: passing mention<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sakura-airi-y1v5-p54-1\">→ After: Ch.4 §4: Last place, then the worst pair<\/button><\/div><\/article>"},{"i":"sc-shinohara-satsuki-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"horikita-suzune sudou-ken shinohara-satsuki","q":"shinohara satsuki ch 3  3  objects to the ability plan shinohara is the first student to object when sudou claims the recommended events  and she argues her case against horikita for two pages   won t that leave slower people high and dry   i don t want to throw away my shot   i don t want to lose out on private points   not everyone is as smart as you  horikita san  horikita answers that she should study longer and  probably wouldn t win anything anyway  sudou shuts her down    if we lose because of you  will you take responsibility    and the class sides with the ability plan","h":"<article class=\"card\" id=\"sc-shinohara-satsuki-y1v5-p39-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shinohara-satsuki.html#sc-shinohara-satsuki-y1v5-p39-1\">Ch.3 §3: Objects to the ability plan<\/a><\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><span class=\"by\">notes on <a href=\"../../../people/shinohara-satsuki.html\">Shinohara Satsuki<\/a><\/span><\/h3><p class=\"setup\">Shinohara is the first student to object when Sudou claims the recommended events, and she argues her case against Horikita for two pages.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shinohara Satsuki<\/b> “Won’t that leave slower people high and dry?”<span class=\"pg\">p.40<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shinohara Satsuki<\/b> “I don’t want to throw away my shot.”<span class=\"pg\">p.40<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shinohara Satsuki<\/b> “I don’t want to lose out on private points.”<span class=\"pg\">p.40<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “Not everyone is as smart as you, Horikita-san.”<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Horikita answers that she should study longer and “probably wouldn’t win anything anyway.”<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Sudou shuts her down — “If we lose because of you, will you take responsibility?” — and the class sides with the ability plan.<span class=\"pg\">p.41<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-sotomura-hideo-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"hirata-yousuke ike-kanji sotomura-hideo","q":"sotomura hideo ch 3  3  the professor s bad luck sotomura    the professor    is called up for the grip strength test alongside sudou  then loses the rock paper scissors for the scavenger hunt  hirata pairs him with sudou for simultaneous measurements   well then  let s have sotomura kun stand next to you and take his measurement simultaneously  sudou kun  posts 42 kilograms of grip strength  the class s lowest printed score  wails when picked for the scavenger hunt    i i have been chosen to participate in the scavenger hunt   why  oh why did i throw rock at that moment","h":"<article class=\"card\" id=\"sc-sotomura-hideo-y1v5-p39-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sotomura-hideo.html#sc-sotomura-hideo-y1v5-p39-1\">Ch.3 §3: The Professor’s bad luck<\/a><\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><span class=\"by\">notes on <a href=\"../../../people/sotomura-hideo.html\">Sotomura Hideo<\/a><\/span><\/h3><p class=\"setup\">Sotomura — “the Professor” — is called up for the grip-strength test alongside Sudou, then loses the rock-paper-scissors for the scavenger hunt.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sotomura Hideo<\/b> “Why, oh why did I throw rock at that moment?”<span class=\"pg\">p.52<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Hirata pairs him with Sudou for simultaneous measurements: “Well then, let’s have Sotomura-kun stand next to you and take his measurement simultaneously, Sudou-kun”<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Posts 42 kilograms of grip strength, the class’s lowest printed score.<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Wails when picked for the scavenger hunt — “I-I have been chosen to participate in the scavenger hunt?”<span class=\"pg\">p.52<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sotomura-hideo-y1v5-p54-1\">→ After: Ch.4 §4: Sits out the tests<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"action spoken","w":"shinohara-satsuki kouenji-rokusuke ayanokouji-kiyotaka sudou-ken","q":"sudo ken ch 3  3  the ability camp  then the grip strength king sudou argues the ability side of hirata s blackboard and  by p 40  has claimed every recommended competition for himself   if i win  then it s more likely our class wins   i ll do all the events for recommended participants  turns his new leadership on shinohara    if we lose because of you  will you take responsibility  huh  votes horikita   when winners win  we all win  claims every recommended competition and warns the class    i ll participate in every competition  confronts koenji for abstaining   hey  kouenji  ain t you gonna cooperate  posts 82 4 kilograms of grip strength   the highest printed score   and bellows through the test   this is what a real man looks like   it s just  cause i train all the time  taunts koenji for refusing the meter   what  you scared of losing to me or something   maybe  like  around 60    his guess at the average  which ayanokoji uses to stop his own meter at 60 6  despairs at the class s depth   man  i can t rely on a single one of you","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v5-p39-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sudou-ken.html#sc-sudou-ken-y1v5-p39-1\">Ch.3 §3: The ability camp, then the grip-strength king<\/a><\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><span class=\"by\">notes on <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/span><\/h3><p class=\"setup\">Sudou argues the ability side of Hirata’s blackboard and, by p.40, has claimed every recommended competition for himself.<\/p><p class=\"with\">with <a href=\"../../../people/shinohara-satsuki.html\">Shinohara Satsuki<\/a> · <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “If I win, then it’s more likely our class wins.”<span class=\"pg\">p.40<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “I’ll do all the events for recommended participants,”<span class=\"pg\">p.40<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “It’s just ’cause I train all the time.”<span class=\"pg\">p.49<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shinohara Satsuki<\/b> Turns his new leadership on Shinohara — “If we lose because of you, will you take responsibility? Huh?”<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Votes Horikita: “When winners win, we all win.”<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Claims every recommended competition and warns the class — “I’ll participate in every competition.”<span class=\"pg\">p.44<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Confronts Kōenji for abstaining: “Hey, Kouenji. Ain’t you gonna cooperate?”<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Posts 82.4 kilograms of grip strength — the highest printed score — and bellows through the test: “This is what a real man looks like.”<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Taunts Kōenji for refusing the meter: “What? You scared of losing to me or something?”<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Maybe, like, around 60?” — his guess at the average, which Ayanokōji uses to stop his own meter at 60.6.<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Despairs at the class’s depth: “Man, I can’t rely on a single one of you.”<span class=\"pg\">p.51<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p16-1\">← Before: Ch.2 §2.1: the huddle<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p54-1\">→ After: Ch.4 §4: The name bet and the leader’s first week<\/button><\/div><\/article>"},{"i":"sc-yukimura-teruhiko-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"action","w":"hirata-yousuke hondou-ryoutaro ayanokouji-kiyotaka yukimura-teruhiko","q":"yukimura teruhiko ch 3  3  hands  votes and the roster yukimura is named among the students who follow sudou into horikita s camp  and he later handles the grip strength device and makes the scavenger hunt roster  raises his hand with sudou and sakura for horikita s ability plan  takes his turn at the grip strength meter after sudou s 82 4  is handed a grip strength device by hirata  alongside hondou  picked with ayanokoji  sotomura  mori and maezono for the scavenger hunt   ayanokouji kun  yukimura kun  sotomura kun  mori san  and maezono san","h":"<article class=\"card\" id=\"sc-yukimura-teruhiko-y1v5-p39-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yukimura-teruhiko.html#sc-yukimura-teruhiko-y1v5-p39-1\">Ch.3 §3: Hands, votes and the roster<\/a><\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><span class=\"by\">notes on <a href=\"../../../people/yukimura-teruhiko.html\">Yukimura Teruhiko<\/a><\/span><\/h3><p class=\"setup\">Yukimura is named among the students who follow Sudou into Horikita’s camp, and he later handles the grip-strength device and makes the scavenger-hunt roster.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/index.html#hondou-ryoutaro\">Hondō Ryōtaro<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q action\">Raises his hand with Sudou and Sakura for Horikita’s ability plan.<span class=\"pg\">p.43<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Takes his turn at the grip-strength meter after Sudou’s 82.4.<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hondō Ryōtaro<\/b> Is handed a grip-strength device by Hirata, alongside Hondou.<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Picked with Ayanokōji, Sotomura, Mori and Maezono for the scavenger hunt: “Ayanokouji-kun, Yukimura-kun, Sotomura-kun, Mori-san, and Maezono-san.”<span class=\"pg\">p.52<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-private-points-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"","w":"","q":"private points ch 3  3  class d s festival point compromise horikita s compromise  carried by the class vote  top placers who don t need test score boosts spend their private points lifting the bottom placers  test scores  and the whole class shares the festival s gains and losses in private points  the narrator notes the cost   chances of victory drop across the board  and the bottom ten students per grade would still be in trouble","h":"<article class=\"card\" id=\"sc-private-points-y1v5-p39-1\"><h3><span class=\"ttl\"><a href=\"../../../school/system/private-points.html#sc-private-points-y1v5-p39-1\">Ch.3 §3: Class D’s festival point compromise<\/a><\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><span class=\"by\">notes on <a href=\"../../../school/system/private-points.html\">Private Points<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Rule<\/span> Horikita’s compromise, carried by the class vote: top placers who don’t need test-score boosts spend their private points lifting the bottom placers’ test scores, and the whole class shares the festival’s gains and losses in private points.<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Effect<\/span> The narrator notes the cost — chances of victory drop across the board, and the bottom ten students per grade would still be in trouble.<span class=\"pg\">p.42<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-private-points-y1v5-p17-1\">← Before: Ch.2: the sports festival’s point economy<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y1v5-p54-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"ryuuen-kakeru horikita-suzune hirata-yousuke kushida-kikyou ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 4  4  the ryuuen read  the partner lesson  the two problems first independent practice on the athletic grounds  class a and b watch from the windows  class c does not  and ayanokoji and horikita talk strategy at the edge of the field  reads the missing reconnaissance as the tell   he s making it obvious by not bothering to do any reconnaissance   normally  when someone has a secret plan in place  they do whatever it takes to ensure that their enemies don t figure it out  lets her pin him down on his pe record    nope  i m not confident    after she calls his scores average   i m sorry to disappoint  but what you see is what you get   would i do something so pointless    when she asks if he is holding back like he did on tests   you ll learn the answer to that soon enough  pairs with hirata for three legged practice after horikita s partnership with onodera collapses  finds the rhythm quickly   hirata s praise makes the awkward drill feel simple  invites himself as her three legged partner   partner with me for the three legged race  outpaces her on purpose  then gives the lesson   this wasn t about fast or slow   the important thing is to work with your partner  names his two problems for the class  horikita  who cannot keep a partner  and kushida  whose rooftop darkness and hatred of horikita must be confronted   therefore  the only way to resolve the issue was to have them confront one another  the praise after sakura s last place finish    you really gave it your all    carries no speaker tag  sakura s reply addresses ayanokouji kun  so it is recorded here rather than assigned outright","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v5-p54-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v5-p54-1\">Ch.4 §4: The Ryuuen read, the partner lesson, the two problems<\/a><\/span><span class=\"meta\">Y1V5 · p.54–67<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">First independent practice on the athletic grounds: Class A and B watch from the windows, Class C does not, and Ayanokōji and Horikita talk strategy at the edge of the field.<\/p><p class=\"with\">with <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Normally, when someone has a secret plan in place, they do whatever it takes to ensure that their enemies don’t figure it out.”<span class=\"pg\">p.55<\/span><\/li><\/ul><details class=\"more\"><summary>13 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Reads the missing reconnaissance as the tell: “He’s making it obvious by not bothering to do any reconnaissance,”<span class=\"pg\">p.55<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Lets her pin him down on his PE record — “Nope, I’m not confident.” — after she calls his scores average.<span class=\"pg\">p.60<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “I’m sorry to disappoint, but what you see is what you get.”<span class=\"pg\">p.60<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “Would I do something so pointless?” — when she asks if he is holding back like he did on tests.<span class=\"pg\">p.61<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “You’ll learn the answer to that soon enough.”<span class=\"pg\">p.61<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Pairs with Hirata for three-legged practice after Horikita’s partnership with Onodera collapses.<span class=\"pg\">p.62<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Finds the rhythm quickly — Hirata’s praise makes the awkward drill feel simple.<span class=\"pg\">p.63<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Invites himself as her three-legged partner: “Partner with me for the three-legged race.”<span class=\"pg\">p.64<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Outpaces her on purpose, then gives the lesson: “This wasn’t about fast or slow.”<span class=\"pg\">p.65<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “The important thing is to work with your partner.”<span class=\"pg\">p.65<\/span><\/li><li><span class=\"mlabel\">Goal<\/span> Names his two problems for the class: Horikita, who cannot keep a partner, and Kushida, whose rooftop darkness and hatred of Horikita must be confronted.<span class=\"pg\">p.66<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> “Therefore, the only way to resolve the issue was to have them confront one another.”<span class=\"pg\">p.66<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The praise after Sakura’s last-place finish — “You really gave it your all.” — carries no speaker tag; Sakura’s reply addresses Ayanokouji-kun, so it is recorded here rather than assigned outright.<span class=\"pg\">p.57<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v5-p39-1\">← Before: Ch.3 §3: The blackboard vote, the betrayal warning, the roster<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v5-p68-1\">→ After: Ch.5 §5: The invitation, the theory, the exit<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y1v5-p54-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"sakura-airi sudou-ken katsuragi-kouhei horikita-suzune ayanokouji-kiyotaka hirata-yousuke","q":"hirata yosuke ch 4  4  gentle methods  three legged partner hirata records the aptitude scores and asks sudou to take the festival leadership  records sakura s last place finish  the praise line that follows is untagged  and sakura answers ayanokouji kun   would you mind leading our class for this  keeps up the periodic class a meetings with katsuragi on how best to compete  fixes the cavalry girls  carriage by millimetres    let s change the positioning a bit  calls ayanokoji over for a three legged pair after horikita s partnership fails   it s really  really easy with ayanokouji kun as my partner  finishes his own practice and is straight off advising others   the class s default gentle teacher","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y1v5-p54-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y1v5-p54-1\">Ch.4 §4: Gentle methods, three-legged partner<\/a><\/span><span class=\"meta\">Y1V5 · p.54–67<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">Hirata records the aptitude scores and asks Sudou to take the festival leadership.<\/p><p class=\"with\">with <a href=\"../../../people/sakura-airi.html\">Sakura Airi<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a> · <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “It’s really, really easy with Ayanokouji-kun as my partner.”<span class=\"pg\">p.63<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakura Airi<\/b> Records Sakura’s last-place finish; the praise line that follows is untagged, and Sakura answers Ayanokouji-kun.<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> “Would you mind leading our class for this?”<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Keeps up the periodic Class A meetings with Katsuragi on how best to compete.<span class=\"pg\">p.64<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Fixes the cavalry girls’ carriage by millimetres — “Let’s change the positioning a bit.”<span class=\"pg\">p.60<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Calls Ayanokōji over for a three-legged pair after Horikita’s partnership fails.<span class=\"pg\">p.62<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Finishes his own practice and is straight off advising others — the class’s default gentle teacher.<span class=\"pg\">p.63<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v5-p39-1\">← Before: Ch.3 §3: Runs the homeroom, the vote and the roster<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v5-p68-1\">→ After: Ch.5 §5: On the pitch and at the podium<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y1v5-p54-1","v":"y1v5","y":1,"o":6,"k":"","w":"ryuuen-kakeru sudou-ken hirata-yousuke ayanokouji-kiyotaka onodera horikita-suzune","q":"horikita suzune ch 4  4  the name bet and the partner problem horikita talks strategy at the first practice  then is interrupted by sudou calling her by her first name   surely the other students must think they re safe  though    on the classes watching d practice   anyone would want information on the other classes   i ve told you numerous times  please do not call me by my first name   if you continue to call me  suzune  after this warning  i ll have to take more direct action to make you stop   hard work is its own reward  why should i agree to such an idiotic bet  takes his bet and raises the bar   if you produce the best results  i will allow you to use my first name   show me that you can be the best out of everyone in our grade  the penalty clause   however  in the event that you don t get first place  i ll forever forbid you from saying my first name  neither encourages nor rejects his leadership claim   i wouldn t object to you serving as leader in this   don t get overconfident and sloppy  because i ll make you pay for that  watches his coaching with dry approval   leadership might actually suit him  don t you think   i don t want to teach them    refuses to coach the cavalry girls   you always get average scores    her read on his pe performance   i might not be able to reach class a just by improving my own skills    an uncharacteristically timid admission  fights with onodera through two three legged runs and comes in third  blamed for the pace  rejects every partner until ayanokouji offers himself   if i m expected to yield  my partner must put in the effort first  loses the demonstration run and is told to look at her partner instead of the clock","h":"<article class=\"card\" id=\"sc-horikita-suzune-y1v5-p54-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y1v5-p54-1\">Ch.4 §4: The name bet and the partner problem<\/a><\/span><span class=\"meta\">Y1V5 · p.54–67<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">Horikita talks strategy at the first practice, then is interrupted by Sudou calling her by her first name.<\/p><p class=\"with\">with <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/index.html#onodera\">Onodera<\/a><\/p><details class=\"more\"><summary>17 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> “Surely the other students must think they’re safe, though.” — on the classes watching D practice.<span class=\"pg\">p.54<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> “Anyone would want information on the other classes.”<span class=\"pg\">p.54<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> “I’ve told you numerous times. Please do not call me by my first name.”<span class=\"pg\">p.55<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> “If you continue to call me ‘Suzune’ after this warning, I’ll have to take more direct action to make you stop.”<span class=\"pg\">p.55<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> “Hard work is its own reward. Why should I agree to such an idiotic bet?”<span class=\"pg\">p.55<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Takes his bet and raises the bar: “If you produce the best results, I will allow you to use my first name.”<span class=\"pg\">p.55<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> “Show me that you can be the best out of everyone in our grade,”<span class=\"pg\">p.55<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> The penalty clause: “However, in the event that you don’t get first place, I’ll forever forbid you from saying my first name.”<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Neither encourages nor rejects his leadership claim: “I wouldn’t object to you serving as leader in this.”<span class=\"pg\">p.58<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> “Don’t get overconfident and sloppy, because I’ll make you pay for that,”<span class=\"pg\">p.58<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Watches his coaching with dry approval: “Leadership might actually suit him, don’t you think?”<span class=\"pg\">p.59<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> “I don’t want to teach them.” — refuses to coach the cavalry girls.<span class=\"pg\">p.60<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> “You always get average scores.” — her read on his PE performance.<span class=\"pg\">p.60<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> “I might not be able to reach Class A just by improving my own skills,” — an uncharacteristically timid admission.<span class=\"pg\">p.61<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Onodera<\/b> Fights with Onodera through two three-legged runs and comes in third; blamed for the pace.<span class=\"pg\">p.62<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Rejects every partner until Ayanokouji offers himself: “If I’m expected to yield, my partner must put in the effort first.”<span class=\"pg\">p.64<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Loses the demonstration run and is told to look at her partner instead of the clock.<span class=\"pg\">p.65<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v5-p39-1\">← Before: Ch.3 §3: Her plan wins the vote<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v5-p68-1\">→ After: Ch.5 §5: The theory, the ally question, the anchor<\/button><\/div><\/article>"},{"i":"sc-ike-kanji-y1v5-p54-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"sudou-ken ike-kanji","q":"ike kanji ch 4  4  the watching classes and the tug demo ike spots class b and a students watching the first practice from the school building windows   hey  they re from class b  right  on the receiving end of sudou s tug of war demonstration   he and yamauchi go down in seconds  gets dirt kicked at him when sudou loses patience with the pull","h":"<article class=\"card\" id=\"sc-ike-kanji-y1v5-p54-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ike-kanji.html#sc-ike-kanji-y1v5-p54-1\">Ch.4 §4: The watching classes and the tug demo<\/a><\/span><span class=\"meta\">Y1V5 · p.54–67<\/span><span class=\"by\">notes on <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a><\/span><\/h3><p class=\"setup\">Ike spots Class B and A students watching the first practice from the school-building windows.<\/p><p class=\"with\">with <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ike Kanji<\/b> “Hey, they’re from Class B, right?”<span class=\"pg\">p.54<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> On the receiving end of Sudou’s tug-of-war demonstration — he and Yamauchi go down in seconds.<span class=\"pg\">p.59<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Gets dirt kicked at him when Sudou loses patience with the pull.<span class=\"pg\">p.60<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ike-kanji-y1v5-p39-1\">← Before: Ch.3 §3: Grip strength and the scavenger hunt<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ike-kanji-y1v5-p68-1\">→ After: Ch.5 §5: Rumors and suspicion<\/button><\/div><\/article>"},{"i":"sc-inogashira-kokoro-y1v5-p54-1","v":"y1v5","y":1,"o":6,"k":"","w":"sakura-airi inogashira-kokoro","q":"inogashira kokoro ch 4  4  the slowest pair inogashira runs the three legged race with sakura   the worst of the five girl pairs   slow as molasses  their third place last finish is what prompts horikita and onodera to try the race again","h":"<article class=\"card\" id=\"sc-inogashira-kokoro-y1v5-p54-1\"><h3><span class=\"ttl\"><a href=\"../../../people/inogashira-kokoro.html#sc-inogashira-kokoro-y1v5-p54-1\">Ch.4 §4: The slowest pair<\/a><\/span><span class=\"meta\">Y1V5 · p.54–67<\/span><span class=\"by\">notes on <a href=\"../../../people/inogashira-kokoro.html\">Inogashira Kokoro<\/a><\/span><\/h3><p class=\"setup\">Inogashira runs the three-legged race with Sakura — the worst of the five girl pairs, “slow as molasses.”<\/p><p class=\"with\">with <a href=\"../../../people/sakura-airi.html\">Sakura Airi<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakura Airi<\/b> Their third-place-last finish is what prompts Horikita and Onodera to try the race again.<span class=\"pg\">p.62<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-katsuragi-kouhei-y1v5-p54-1","v":"y1v5","y":1,"o":6,"k":"","w":"hirata-yousuke ryuuen-kakeru katsuragi-kouhei","q":"katsuragi kohei ch 4  4  the standing class a meetings katsuragi is named as hirata s periodic counterpart on how the two classes should compete  meetings continue through the run up   class d  an inch from disaster  is doing almost too well  background  ryuuen refused to cooperate with class b earlier in the volume  so no class c b channel exists","h":"<article class=\"card\" id=\"sc-katsuragi-kouhei-y1v5-p54-1\"><h3><span class=\"ttl\"><a href=\"../../../people/katsuragi-kouhei.html#sc-katsuragi-kouhei-y1v5-p54-1\">Ch.4 §4: The standing Class A meetings<\/a><\/span><span class=\"meta\">Y1V5 · p.54–67<\/span><span class=\"by\">notes on <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/span><\/h3><p class=\"setup\">Katsuragi is named as Hirata’s periodic counterpart on how the two classes should compete.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Meetings continue through the run-up — Class D, an inch from disaster, is doing almost too well.<span class=\"pg\">p.64<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Background: Ryuuen refused to cooperate with Class B earlier in the volume, so no Class C–B channel exists.<span class=\"pg\">p.54–55<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-katsuragi-kouhei-y1v5-p26-1\">← Before: Ch.2 §2.2: the Class A face<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-katsuragi-kouhei-y1v5-p68-1\">→ After: Ch.5 §5: Named in the cruise-ship theory<\/button><\/div><\/article>"},{"i":"sc-kouenji-rokusuke-y1v5-p54-1","v":"y1v5","y":1,"o":6,"k":"","w":"sudou-ken kouenji-rokusuke","q":"koenji rokusuke ch 4  4  sits out the tests koenji is named among the few who sit out the aptitude testing   along with the professor  sudou s grudge  nobody in the class has seen him run seriously  though he beat sudou s swimming time  won t budge unless he wants to   his skill is obvious  his participation isn t","h":"<article class=\"card\" id=\"sc-kouenji-rokusuke-y1v5-p54-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kouenji-rokusuke.html#sc-kouenji-rokusuke-y1v5-p54-1\">Ch.4 §4: Sits out the tests<\/a><\/span><span class=\"meta\">Y1V5 · p.54–67<\/span><span class=\"by\">notes on <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/span><\/h3><p class=\"setup\">Kōenji is named among the few who sit out the aptitude testing — along with the Professor.<\/p><p class=\"with\">with <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Sudou’s grudge: nobody in the class has seen him run seriously, though he beat Sudou’s swimming time.<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Won’t budge unless he wants to — his skill is obvious, his participation isn’t.<span class=\"pg\">p.57<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y1v5-p39-1\">← Before: Ch.3 §3: Refuses to cooperate<\/button><\/div><\/article>"},{"i":"sc-kushida-kikyou-y1v5-p54-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"sudou-ken ayanokouji-kiyotaka horikita-suzune kushida-kikyou","q":"kushida kikyo ch 4  4  names sudou the leader  named the second problem kushida cheers sudou through the aptitude tests and is the first to call him the festival leader   you always end up taking first place in our class  no matter the event   really  sudou kun  you re definitely the sports festival leader  her praise is what pushes sudou toward the leadership hirata then offers  ayanokoji s second problem  a backstage supporting character with unusual influence  academically and physically gifted   and assigned to class d as a mystery  he knows she hates horikita from an early rooftop rant  and resolves that the two must confront each other","h":"<article class=\"card\" id=\"sc-kushida-kikyou-y1v5-p54-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kushida-kikyou.html#sc-kushida-kikyou-y1v5-p54-1\">Ch.4 §4: Names Sudou the leader; named the second problem<\/a><\/span><span class=\"meta\">Y1V5 · p.54–67<\/span><span class=\"by\">notes on <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a><\/span><\/h3><p class=\"setup\">Kushida cheers Sudou through the aptitude tests and is the first to call him the festival leader.<\/p><p class=\"with\">with <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kushida Kikyō<\/b> “You always end up taking first place in our class, no matter the event.”<span class=\"pg\">p.57<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kushida Kikyō<\/b> “Really, Sudou-kun, you’re definitely the sports festival leader,”<span class=\"pg\">p.57<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Her praise is what pushes Sudou toward the leadership Hirata then offers.<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Ayanokōji’s second problem: a backstage supporting character with unusual influence, academically and physically gifted — and assigned to Class D as a mystery.<span class=\"pg\">p.65–66<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> He knows she hates Horikita from an early rooftop rant, and resolves that the two must confront each other.<span class=\"pg\">p.66<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kushida-kikyou-y1v5-p39-1\">← Before: Ch.3 §3: Asked for the middle ground<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kushida-kikyou-y1v5-p68-1\">→ After: Ch.5 §5: “It’s me”<\/button><\/div><\/article>"},{"i":"sc-onodera-y1v5-p54-1","v":"y1v5","y":1,"o":6,"k":"","w":"horikita-suzune onodera","q":"onodera ch 4  4  three legged partner for horikita onodera  the swimming club sprinter  is paired with horikita for three legged race practice   and they come in third  two failed runs   hey  horikita san  can t you try to keep pace with me better  horikita answers that onodera is the slow one  the partnership dissolves on the spot","h":"<article class=\"card\" id=\"sc-onodera-y1v5-p54-1\"><h3><span class=\"ttl\">Ch.4 §4: Three-legged partner for Horikita<\/span><span class=\"meta\">Y1V5 · p.54–67<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#onodera\">Onodera<\/a><\/span><\/h3><p class=\"setup\">Onodera, the swimming-club sprinter, is paired with Horikita for three-legged race practice — and they come in third.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Two failed runs: “Hey, Horikita-san, can’t you try to keep pace with me better?”<span class=\"pg\">p.62<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Horikita answers that Onodera is the slow one; the partnership dissolves on the spot.<span class=\"pg\">p.62<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-onodera-y1v5-p39-1\">← Before: Ch.3 §3: Volunteers for the recommended events<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y1v5-p54-1","v":"y1v5","y":1,"o":6,"k":"","w":"horikita-suzune ayanokouji-kiyotaka ryuuen-kakeru","q":"ryuen kakeru ch 4  4  the reconnaissance that isn t ayanokoji and horikita discuss ryuuen at the edge of the first practice  not one class c student is watching d  she reads the silence as a strategy already in place    reconnaissance isn t necessary for him  the tell is that he isn t hiding it  making the absence of reconnaissance obvious is itself the display  ryuuen s non scouting reads as a message to the other classes  not as disinterest","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y1v5-p54-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y1v5-p54-1\">Ch.4 §4: The reconnaissance that isn’t<\/a><\/span><span class=\"meta\">Y1V5 · p.54–67<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"setup\">Ayanokōji and Horikita discuss Ryuuen at the edge of the first practice: not one Class C student is watching D.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> She reads the silence as a strategy already in place — “Reconnaissance isn’t necessary for him.”<span class=\"pg\">p.54–55<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> The tell is that he isn’t hiding it: making the absence of reconnaissance obvious is itself the display.<span class=\"pg\">p.55<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Ryuuen’s non-scouting reads as a message to the other classes, not as disinterest.<span class=\"pg\">p.54–55<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y1v5-p27-1\">← Before: Ch.2 §2.2: the walkout<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y1v5-p68-1\">→ After: Ch.5 §5: Named in the cruise-ship theory<\/button><\/div><\/article>"},{"i":"sc-sakura-airi-y1v5-p54-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"inogashira-kokoro sakura-airi","q":"sakura airi ch 4  4  last place  then the worst pair sakura finishes last in the aptitude tests  barely able to stand  and is praised for giving it her all   a ayanokouji kun  works hard to contribute for the class  but her lack of physical endurance is still the problem  pairs with inogashira for the three legged race   the slowest of the five girl pairs   slow as molasses","h":"<article class=\"card\" id=\"sc-sakura-airi-y1v5-p54-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakura-airi.html#sc-sakura-airi-y1v5-p54-1\">Ch.4 §4: Last place, then the worst pair<\/a><\/span><span class=\"meta\">Y1V5 · p.54–67<\/span><span class=\"by\">notes on <a href=\"../../../people/sakura-airi.html\">Sakura Airi<\/a><\/span><\/h3><p class=\"setup\">Sakura finishes last in the aptitude tests, barely able to stand, and is praised for giving it her all.<\/p><p class=\"with\">with <a href=\"../../../people/inogashira-kokoro.html\">Inogashira Kokoro<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sakura Airi<\/b> “A-Ayanokouji-kun.”<span class=\"pg\">p.57<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Works hard to contribute for the class, but her lack of physical endurance is still the problem.<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Inogashira Kokoro<\/b> Pairs with Inogashira for the three-legged race — the slowest of the five girl pairs, “slow as molasses.”<span class=\"pg\">p.62<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakura-airi-y1v5-p39-1\">← Before: Ch.3 §3: Follows Sudou’s hand<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sakura-airi-y1v5-p68-1\">→ After: Ch.5 §5: Named in passing<\/button><\/div><\/article>"},{"i":"sc-sotomura-hideo-y1v5-p54-1","v":"y1v5","y":1,"o":6,"k":"","w":"sotomura-hideo","q":"sotomura hideo ch 4  4  sits out the tests sotomura   the professor   is named with koenji as one of the few who sit out the aptitude testing  opts out of the physical tests while roughly 90 percent of the class takes part","h":"<article class=\"card\" id=\"sc-sotomura-hideo-y1v5-p54-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sotomura-hideo.html#sc-sotomura-hideo-y1v5-p54-1\">Ch.4 §4: Sits out the tests<\/a><\/span><span class=\"meta\">Y1V5 · p.54–67<\/span><span class=\"by\">notes on <a href=\"../../../people/sotomura-hideo.html\">Sotomura Hideo<\/a><\/span><\/h3><p class=\"setup\">Sotomura — the Professor — is named with Kōenji as one of the few who sit out the aptitude testing.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> opts out of the physical tests while roughly 90 percent of the class takes part.<span class=\"pg\">p.57<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sotomura-hideo-y1v5-p39-1\">← Before: Ch.3 §3: The Professor’s bad luck<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v5-p54-1","v":"y1v5","y":1,"o":6,"k":"","w":"horikita-suzune kushida-kikyou kouenji-rokusuke hirata-yousuke ike-kanji sudou-ken","q":"sudo ken ch 4  4  the name bet and the leader s first week sudou arrives mid practice and calls horikita by her first name  starting the chapter s central bet   you have a minute    how the  suzune  address opens   not too long ago  you saved me    why he wants to do things properly   i think i d like to be friends with you  first  accepts the grade wide bar   if i place first in our grade level  i ll call you by your first name  goes  y yeah  when she adds the forever forbidden penalty  unbeatable in the aptitude tests   kushida calls him the sports festival leader  glares at koenji over the untested running question   even so  i dunno what ll happen if he runs  handed the leadership by hirata   would you mind leading our class for this   i ain t really suited to be a leader or anythin   okay  i ll lead our class to victory    living up to her half approval  coaches tug of war by demonstration  beating ike and yamauchi in seconds  and teaches hips over arms   look  i m tellin  you that ain t it    kicks dirt at ike and yamauchi when they botch the pull  thorough with every student who asks  but his rashness keeps undercutting the gentler style a leader needs","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v5-p54-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sudou-ken.html#sc-sudou-ken-y1v5-p54-1\">Ch.4 §4: The name bet and the leader’s first week<\/a><\/span><span class=\"meta\">Y1V5 · p.54–67<\/span><span class=\"by\">notes on <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/span><\/h3><p class=\"setup\">Sudou arrives mid-practice and calls Horikita by her first name, starting the chapter’s central bet.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a><\/p><details class=\"more\"><summary>13 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “You have a minute?” — how the “Suzune” address opens.<span class=\"pg\">p.55<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “Not too long ago, you saved me.” — why he wants to do things properly.<span class=\"pg\">p.55<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “I think I’d like to be friends with you, first.”<span class=\"pg\">p.55<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Accepts the grade-wide bar: “If I place first in our grade level, I’ll call you by your first name,”<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Goes “Y-yeah” when she adds the forever-forbidden penalty.<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Unbeatable in the aptitude tests — Kushida calls him the sports festival leader.<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Glares at Kōenji over the untested running question: “Even so, I dunno what’ll happen if he runs.”<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Handed the leadership by Hirata: “Would you mind leading our class for this?”<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “I ain’t really suited to be a leader or anythin’…”<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “Okay! I’ll lead our class to victory,” — living up to her half-approval.<span class=\"pg\">p.58<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Coaches tug-of-war by demonstration, beating Ike and Yamauchi in seconds, and teaches hips over arms.<span class=\"pg\">p.59<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> “Look, I’m tellin’ you that ain’t it!” — kicks dirt at Ike and Yamauchi when they botch the pull.<span class=\"pg\">p.59<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Thorough with every student who asks, but his rashness keeps undercutting the gentler style a leader needs.<span class=\"pg\">p.59<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p39-1\">← Before: Ch.3 §3: The ability camp, then the grip-strength king<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p68-1\">→ After: Ch.5 §5: Noodles, first names, and the anchor he gives up<\/button><\/div><\/article>"},{"i":"sc-yamauchi-haruki-y1v5-p54-1","v":"y1v5","y":1,"o":6,"k":"","w":"sudou-ken yamauchi-haruki","q":"yamauchi haruki ch 4  4  on the losing end of the demo yamauchi faces sudou in the tug of war demonstration alongside ike and is pulled down in seconds  gets dirt kicked at him when sudou snaps during the coaching session","h":"<article class=\"card\" id=\"sc-yamauchi-haruki-y1v5-p54-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yamauchi-haruki.html#sc-yamauchi-haruki-y1v5-p54-1\">Ch.4 §4: On the losing end of the demo<\/a><\/span><span class=\"meta\">Y1V5 · p.54–67<\/span><span class=\"by\">notes on <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a><\/span><\/h3><p class=\"setup\">Yamauchi faces Sudou in the tug-of-war demonstration alongside Ike and is pulled down in seconds.<\/p><p class=\"with\">with <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Gets dirt kicked at him when Sudou snaps during the coaching session.<span class=\"pg\">p.60<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamauchi-haruki-y1v5-p23-1\">← Before: Ch.2 §2.1: the huddle<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamauchi-haruki-y1v5-p68-1\">→ After: Ch.5 §5: The Sakura defeat still stings<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y1v5-p68-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"kushida-kikyou horikita-suzune sakayanagi-arisu ike-kanji sudou-ken shibata-sou ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 5  5  the invitation  the theory  the exit two weeks before the festival  ayanokoji recruits horikita and kushida for a saturday reconnaissance   the first move against  the bomb waiting to go off inside class d   hang out with me today   you ll understand better if you come with me   kushida  do you have a minute   by the way  horikita will be coming  too   doing a little reconnaissance isn t a bad thing  wouldn t you agree  the theory  flat out   one other person was significantly involved in the outcome on the cruise ship   but what about kushida herself  what if she intentionally exposed her identity   only kushida knows    which is why she is invited   you and kushida seem to have some kind of connection  elevator parting   you re free to choose whether or not you come tomorrow  but if you want to lead the class  think about it  probes ike and yamauchi for sakayanagi rumors and gets nothing usable  deflects the message suspicion    absolutely not  so relax  leaves the three to their noodle talk    sorry  guys  i ve got plans  owns the setup when kushida calls it   why do you think that   it s like i half believe it  and half don t  asks the question outright   why don t you and horikita like each other  tells hirata the truth of the outing    we re spying  sets the stage for horikita s vip question  then leaves the two girls alone  glosses horikita s brother trouble for the group    some stuff happened  i guess horikita and her brother aren t really on speaking terms","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v5-p68-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v5-p68-1\">Ch.5 §5: The invitation, the theory, the exit<\/a><\/span><span class=\"meta\">Y1V5 · p.68–85<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Two weeks before the festival, Ayanokōji recruits Horikita and Kushida for a Saturday reconnaissance — the first move against “the bomb waiting to go off inside Class D.”<\/p><p class=\"with\">with <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a> · <a href=\"../../../people/shibata-sou.html\">Shibata Sō<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Hang out with me today.”<span class=\"pg\">p.68<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “You’ll understand better if you come with me.”<span class=\"pg\">p.68<\/span><\/li><\/ul><details class=\"more\"><summary>17 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> “Kushida, do you have a minute?”<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> “By the way, Horikita will be coming, too.”<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “Doing a little reconnaissance isn’t a bad thing, wouldn’t you agree?”<span class=\"pg\">p.69<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> The theory, flat out: “One other person was significantly involved in the outcome on the cruise ship,”<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> “But what about Kushida herself? What if she intentionally exposed her identity?”<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> “Only Kushida knows.” — which is why she is invited.<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “You and Kushida seem to have some kind of connection.”<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Elevator parting: “You’re free to choose whether or not you come tomorrow, but if you want to lead the class, think about it.”<span class=\"pg\">p.71<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Probes Ike and Yamauchi for Sakayanagi rumors and gets nothing usable.<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Deflects the message suspicion — “Absolutely not, so relax.”<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Leaves the three to their noodle talk — “Sorry, guys. I’ve got plans.”<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Owns the setup when Kushida calls it: “Why do you think that?”<span class=\"pg\">p.75<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> “It’s like I half believe it, and half don’t.”<span class=\"pg\">p.75<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Asks the question outright: “Why don’t you and Horikita like each other?”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shibata Sō<\/b> Tells Hirata the truth of the outing — “We’re spying.”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Sets the stage for Horikita’s VIP question, then leaves the two girls alone.<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Glosses Horikita’s brother trouble for the group — “Some stuff happened. I guess Horikita and her brother aren’t really on speaking terms.”<span class=\"pg\">p.84<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v5-p54-1\">← Before: Ch.4 §4: The Ryuuen read, the partner lesson, the two problems<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y1v5-p68-1","v":"y1v5","y":1,"o":6,"k":"","w":"nagumo-miyabi shibata-sou ayanokouji-kiyotaka sudou-ken horikita-suzune hirata-yousuke","q":"hirata yosuke ch 5  5  on the pitch and at the podium hirata is playing in the mixed year soccer practice the trio comes to watch  outplayed by nagumo in the practice game   sharp  but in a different league  walks over with shibata and forms the five person group  calls shibata the fastest in class b  takes the spy confession in stride and warns the group off shibata   personally  i d rather not compete against him  runs the participation table meeting from the podium on data and clear testing   i need more information    refuses to swap the anchor order without a reason  then submits the swapped list","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y1v5-p68-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y1v5-p68-1\">Ch.5 §5: On the pitch and at the podium<\/a><\/span><span class=\"meta\">Y1V5 · p.68–85<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">Hirata is playing in the mixed-year soccer practice the trio comes to watch.<\/p><p class=\"with\">with <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"../../../people/shibata-sou.html\">Shibata Sō<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Outplayed by Nagumo in the practice game — sharp, but in a different league.<span class=\"pg\">p.76–77<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shibata Sō<\/b> Walks over with Shibata and forms the five-person group; calls Shibata the fastest in Class B.<span class=\"pg\">p.79<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Takes the spy confession in stride and warns the group off Shibata: “Personally, I’d rather not compete against him.”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Runs the participation-table meeting from the podium on data and clear testing.<span class=\"pg\">p.82<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “I need more information” — refuses to swap the anchor order without a reason, then submits the swapped list.<span class=\"pg\">p.84<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v5-p54-1\">← Before: Ch.4 §4: Gentle methods, three-legged partner<\/button><\/div><\/article>"},{"i":"sc-horikita-manabu-y1v5-p68-1","v":"y1v5","y":1,"o":6,"k":"","w":"horikita-suzune nagumo-miyabi horikita-manabu","q":"horikita manabu ch 5  5  the brother  revealed to the group horikita s brother is named as the student council president when she asks for the relay anchor   it s because i think my brother is an anchor    the reason the group had been pressing for  nagumo is framed as the candidate whose abilities are on par with the president s  ayanokoji s gloss for the others   the two  aren t really on speaking terms","h":"<article class=\"card\" id=\"sc-horikita-manabu-y1v5-p68-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-manabu.html#sc-horikita-manabu-y1v5-p68-1\">Ch.5 §5: The brother, revealed to the group<\/a><\/span><span class=\"meta\">Y1V5 · p.68–85<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a><\/span><\/h3><p class=\"setup\">Horikita’s brother is named as the student council president when she asks for the relay anchor.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “It’s because I think my brother…is an anchor,” — the reason the group had been pressing for.<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Nagumo is framed as the candidate whose abilities are on par with the president’s.<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Ayanokōji’s gloss for the others — the two “aren’t really on speaking terms.”<span class=\"pg\">p.84<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-manabu-y1v5-p26-1\">← Before: Ch.2: passing mention<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y1v5-p68-1","v":"y1v5","y":1,"o":6,"k":"","w":"ayanokouji-kiyotaka kushida-kikyou nagumo-miyabi sudou-ken horikita-manabu horikita-suzune","q":"horikita suzune ch 5  5  the theory  the ally question  the anchor horikita is pulled into ayanokoji s saturday plan and spends the walk to the dorms listening to his cruise ship theory   and if i say i don t want to   what are you planning   i don t understand the reason for inviting me   of course  everyone discovered our vip s identity   that s impossible  right    on kushida exposing herself   even if that s possible  it would hurt class d   so  you re saying that kushida would betray her allies to gain a few measly points   kushida san and i have no bond whatsoever  shows up at the lobby in a bad mood she tries to hide   information is invaluable  we don t know what might be the key to our victory   i m impressed that you have the nerve to say that when i m standing right here  will not concede nagumo s skill    he s just really athletic  that s all  cuts to the heart   during the cruise ship exam  did you tell ryuuen kun or katsuragi kun that you were the vip  the demand that matters   can i trust you to be our class s ally from this point on  asks sudou for the 1200 metre relay anchor and defends the pick    i know your abilities from seeing you practice  reveals why   it s because i think my brother is an anchor  gets the anchor handed back to her once the reason is on the table","h":"<article class=\"card\" id=\"sc-horikita-suzune-y1v5-p68-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y1v5-p68-1\">Ch.5 §5: The theory, the ally question, the anchor<\/a><\/span><span class=\"meta\">Y1V5 · p.68–85<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">Horikita is pulled into Ayanokōji’s Saturday plan and spends the walk to the dorms listening to his cruise-ship theory.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a> · <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a><\/p><details class=\"more\"><summary>17 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> “And if I say I don’t want to?”<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> “What are you planning?”<span class=\"pg\">p.69<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> “I don’t understand the reason for inviting me.”<span class=\"pg\">p.69<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Of course. Everyone discovered our VIP’s identity.”<span class=\"pg\">p.69<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> “That’s impossible, right?” — on Kushida exposing herself.<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Even if that’s possible, it would hurt Class D.”<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> “So, you’re saying that Kushida would betray her allies to gain a few measly points?”<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> “Kushida-san and I have no bond whatsoever,”<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Shows up at the lobby in a bad mood she tries to hide.<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> “Information is invaluable. We don’t know what might be the key to our victory,”<span class=\"pg\">p.75<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> “I’m impressed that you have the nerve to say that when I’m standing right here,”<span class=\"pg\">p.75<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Will not concede Nagumo’s skill — “He’s just really athletic, that’s all.”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Cuts to the heart: “During the cruise ship exam, did you tell Ryuuen-kun or Katsuragi-kun that you were the VIP?”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> The demand that matters: “Can I trust you to be our class’s ally from this point on?”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Asks Sudou for the 1200-metre relay anchor and defends the pick — “I know your abilities from seeing you practice,”<span class=\"pg\">p.82–83<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Reveals why: “It’s because I think my brother…is an anchor,”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Gets the anchor handed back to her once the reason is on the table.<span class=\"pg\">p.84<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v5-p54-1\">← Before: Ch.4 §4: The name bet and the partner problem<\/button><\/div><\/article>"},{"i":"sc-ike-kanji-y1v5-p68-1","v":"y1v5","y":1,"o":6,"k":"","w":"sakayanagi-arisu ayanokouji-kiyotaka sudou-ken ike-kanji","q":"ike kanji ch 5  5  rumors and suspicion ike spends saturday in ayanokoji s room and is the one who brings up sakayanagi  on the class a girl   yeah  dude  of course i remember her   she doesn t really put it out there  you know    no usable rumors  notices the messages   you know  dude  you ve been getting lots of messages lately  haven t you  the noodle room trio with sudou and yamauchi through the morning","h":"<article class=\"card\" id=\"sc-ike-kanji-y1v5-p68-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ike-kanji.html#sc-ike-kanji-y1v5-p68-1\">Ch.5 §5: Rumors and suspicion<\/a><\/span><span class=\"meta\">Y1V5 · p.68–85<\/span><span class=\"by\">notes on <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a><\/span><\/h3><p class=\"setup\">Ike spends Saturday in Ayanokōji’s room and is the one who brings up Sakayanagi.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> On the Class A girl: “Yeah, dude, of course I remember her.”<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> “She doesn’t really put it out there, you know?” — no usable rumors.<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Notices the messages: “You know, dude, you’ve been getting lots of messages lately. Haven’t you?”<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> The noodle-room trio with Sudou and Yamauchi through the morning.<span class=\"pg\">p.72–73<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ike-kanji-y1v5-p54-1\">← Before: Ch.4 §4: The watching classes and the tug demo<\/button><\/div><\/article>"},{"i":"sc-karuizawa-kei-y1v5-p68-1","v":"y1v5","y":1,"o":6,"k":"","w":"karuizawa-kei","q":"karuizawa kei ch 5  5  named in passing karuizawa is named only as an alternative ayanokoji considers for the saturday outing  he weighs her or sakura against kushida and decides kushida is the right person   no scene presence this chapter","h":"<article class=\"card\" id=\"sc-karuizawa-kei-y1v5-p68-1\"><h3><span class=\"ttl\"><a href=\"../../../people/karuizawa-kei.html#sc-karuizawa-kei-y1v5-p68-1\">Ch.5 §5: Named in passing<\/a><\/span><span class=\"meta\">Y1V5 · p.68–85<\/span><span class=\"by\">notes on <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/span><\/h3><p class=\"setup\">Karuizawa is named only as an alternative Ayanokōji considers for the Saturday outing.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> He weighs her or Sakura against Kushida and decides Kushida is the right person — no scene presence this chapter.<span class=\"pg\">p.74<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-karuizawa-kei-y1v5-p39-1\">← Before: Ch.3 §3: The other camp, then the entrance meeting<\/button><\/div><\/article>"},{"i":"sc-katsuragi-kouhei-y1v5-p68-1","v":"y1v5","y":1,"o":6,"k":"","w":"kushida-kikyou katsuragi-kouhei","q":"katsuragi kohei ch 5  5  named in the cruise ship theory katsuragi is the other upperclassman horikita names when she asks kushida the vip question   did you tell ryuuen kun or katsuragi kun that you were the vip    the question  with ryuuen","h":"<article class=\"card\" id=\"sc-katsuragi-kouhei-y1v5-p68-1\"><h3><span class=\"ttl\"><a href=\"../../../people/katsuragi-kouhei.html#sc-katsuragi-kouhei-y1v5-p68-1\">Ch.5 §5: Named in the cruise-ship theory<\/a><\/span><span class=\"meta\">Y1V5 · p.68–85<\/span><span class=\"by\">notes on <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/span><\/h3><p class=\"setup\">Katsuragi is the other upperclassman Horikita names when she asks Kushida the VIP question.<\/p><p class=\"with\">with <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> “did you tell Ryuuen-kun or Katsuragi-kun that you were the VIP?” — the question, with Ryuuen.<span class=\"pg\">p.80<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-katsuragi-kouhei-y1v5-p54-1\">← Before: Ch.4 §4: The standing Class A meetings<\/button><\/div><\/article>"},{"i":"sc-kushida-kikyou-y1v5-p68-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"ayanokouji-kiyotaka horikita-suzune shibata-sou sudou-ken kushida-kikyou","q":"kushida kikyo ch 5  5   it s me  kushida is recruited for the saturday outing and accepts with her usual warmth  noting how unusual the invitation is   hmm  what is it  ayanokouji kun   you know  it s really unusual for you to invite me out  ayanokouji kun   we ll meet in the dorm lobby tomorrow morning  then  welcomes horikita to the lobby with an unwavering smile despite the bad mood aimed at her   i feel kind of like a secret agent  spying on clubs to gain information about other classes   it was really kind of you to do this for horikita san s sake  ayanokouji kun  drops the pretense first   ayanokouji kun  you were the one who decided to invite me out today  weren t you   you understand that things aren t good between horikita san and me  don t you  asked why the two dislike each other  she answers   it s me  well informed as ever   knows shibata outclasses hirata and greets nagumo by nickname  answers the ally demand   of course  i want to get to class a  alongside everyone from class d  intervenes in the anchor dispute and backs the swap once sudou is satisfied","h":"<article class=\"card\" id=\"sc-kushida-kikyou-y1v5-p68-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kushida-kikyou.html#sc-kushida-kikyou-y1v5-p68-1\">Ch.5 §5: “It’s me”<\/a><\/span><span class=\"meta\">Y1V5 · p.68–85<\/span><span class=\"by\">notes on <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a><\/span><\/h3><p class=\"setup\">Kushida is recruited for the Saturday outing and accepts with her usual warmth, noting how unusual the invitation is.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/shibata-sou.html\">Shibata Sō<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kushida Kikyō<\/b> “Hmm? What is it, Ayanokouji-kun?”<span class=\"pg\">p.68<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kushida Kikyō<\/b> “You know, it’s really unusual for you to invite me out, Ayanokouji-kun.”<span class=\"pg\">p.68<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kushida Kikyō<\/b> “I feel kind of like a secret agent, spying on clubs to gain information about other classes.”<span class=\"pg\">p.75<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> “We’ll meet in the dorm lobby tomorrow morning, then?”<span class=\"pg\">p.69<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Welcomes Horikita to the lobby with an unwavering smile despite the bad mood aimed at her.<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “it was really kind of you to do this for Horikita-san’s sake, Ayanokouji-kun,”<span class=\"pg\">p.75<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Drops the pretense first: “Ayanokouji-kun, you were the one who decided to invite me out today, weren’t you?”<span class=\"pg\">p.75<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> “You understand that things aren’t good between Horikita-san and me, don’t you?”<span class=\"pg\">p.75<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Asked why the two dislike each other, she answers: “It’s me,”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shibata Sō<\/b> Well-informed as ever — knows Shibata outclasses Hirata and greets Nagumo by nickname.<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Answers the ally demand: “Of course. I want to get to Class A, alongside everyone from Class D.”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Intervenes in the anchor dispute and backs the swap once Sudou is satisfied.<span class=\"pg\">p.83–84<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kushida-kikyou-y1v5-p54-1\">← Before: Ch.4 §4: Names Sudou the leader; named the second problem<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v5-p68-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"kushida-kikyou horikita-suzune horikita-manabu nagumo-miyabi","q":"nagumo miyabi ch 5  5  the practice pitch nagumo strolls onto the soccer pitch mid practice and is greeted by kushida by nickname   i see you re on a date   we don t really hold back here  so i think this is a good way to measure our players  strengths  calls her  kikyou chan  and winks before rejoining the game  outclasses both hirata and shibata in the practice game  then scores from midfield    in a different league  horikita refuses to concede the skill   he s just really athletic  that s all  introduced as the candidate to be next student council president  abilities on par with horikita s older brother","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v5-p68-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nagumo-miyabi.html#sc-nagumo-miyabi-y1v5-p68-1\">Ch.5 §5: The practice pitch<\/a><\/span><span class=\"meta\">Y1V5 · p.68–85<\/span><span class=\"by\">notes on <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/span><\/h3><p class=\"setup\">Nagumo strolls onto the soccer pitch mid-practice and is greeted by Kushida by nickname.<\/p><p class=\"with\">with <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nagumo Miyabi<\/b> “I see you’re on a date.”<span class=\"pg\">p.76<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nagumo Miyabi<\/b> “We don’t really hold back here, so I think this is a good way to measure our players’ strengths,”<span class=\"pg\">p.76<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Calls her “Kikyou-chan” and winks before rejoining the game.<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Outclasses both Hirata and Shibata in the practice game, then scores from midfield — “in a different league.”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Horikita refuses to concede the skill: “He’s just really athletic, that’s all.”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Introduced as the candidate to be next student council president, abilities on par with Horikita’s older brother.<span class=\"pg\">p.76<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ryuuen-kakeru-y1v5-p68-1","v":"y1v5","y":1,"o":6,"k":"","w":"horikita-suzune kushida-kikyou ryuuen-kakeru","q":"ryuen kakeru ch 5  5  named in the cruise ship theory ryuuen is the first name in ayanokoji s theory about how the vip identity leaked  horikita s own dead end   i assume ryuuen kun was involved somehow  horikita puts the direct question to kushida   did she tell ryuuen or katsuragi she was the vip  the theory holds that ryuuen was one party  a second  inside class d  was significantly involved","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y1v5-p68-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y1v5-p68-1\">Ch.5 §5: Named in the cruise-ship theory<\/a><\/span><span class=\"meta\">Y1V5 · p.68–85<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"setup\">Ryuuen is the first name in Ayanokōji’s theory about how the VIP identity leaked.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Horikita’s own dead end: “I assume Ryuuen-kun was involved somehow,”<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Horikita puts the direct question to Kushida — did she tell Ryuuen or Katsuragi she was the VIP?<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> The theory holds that Ryuuen was one party; a second, inside Class D, was significantly involved.<span class=\"pg\">p.70<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y1v5-p54-1\">← Before: Ch.4 §4: The reconnaissance that isn’t<\/button><\/div><\/article>"},{"i":"sc-sakayanagi-arisu-y1v5-p68-1","v":"y1v5","y":1,"o":6,"k":"","w":"ike-kanji yamauchi-haruki sakayanagi-arisu","q":"sakayanagi arisu ch 5  5  rumored from a distance sakayanagi is raised in ayanokoji s room as a possible source of class a information  ike remembers her as  that beautiful girl  no usable rumors come back  yamauchi s contribution  people say she s the class leader and  really  like  mature  the two boys deliver nothing actionable   ayanokoji s question goes nowhere","h":"<article class=\"card\" id=\"sc-sakayanagi-arisu-y1v5-p68-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakayanagi-arisu.html#sc-sakayanagi-arisu-y1v5-p68-1\">Ch.5 §5: Rumored from a distance<\/a><\/span><span class=\"meta\">Y1V5 · p.68–85<\/span><span class=\"by\">notes on <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/span><\/h3><p class=\"setup\">Sakayanagi is raised in Ayanokōji’s room as a possible source of Class A information.<\/p><p class=\"with\">with <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a> · <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Ike remembers her as “that beautiful girl”; no usable rumors come back.<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> Yamauchi’s contribution: people say she’s the class leader and “really, like, mature.”<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The two boys deliver nothing actionable — Ayanokōji’s question goes nowhere.<span class=\"pg\">p.72–73<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y1v5-p28-1\">← Before: Ch.2 §2.2: the introduction<\/button><\/div><\/article>"},{"i":"sc-sakura-airi-y1v5-p68-1","v":"y1v5","y":1,"o":6,"k":"","w":"yamauchi-haruki sakura-airi","q":"sakura airi ch 5  5  named in passing sakura is named as the girl yamauchi confessed to over the summer   and lost  the defeat still shows in yamauchi s forced smile during the noodle talk  ayanokoji considers bringing her or karuizawa to the grounds instead of kushida  but judges the wrong person for the job","h":"<article class=\"card\" id=\"sc-sakura-airi-y1v5-p68-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakura-airi.html#sc-sakura-airi-y1v5-p68-1\">Ch.5 §5: Named in passing<\/a><\/span><span class=\"meta\">Y1V5 · p.68–85<\/span><span class=\"by\">notes on <a href=\"../../../people/sakura-airi.html\">Sakura Airi<\/a><\/span><\/h3><p class=\"setup\">Sakura is named as the girl Yamauchi confessed to over the summer — and lost.<\/p><p class=\"with\">with <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> The defeat still shows in Yamauchi’s forced smile during the noodle talk.<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji considers bringing her or Karuizawa to the grounds instead of Kushida, but judges the wrong person for the job.<span class=\"pg\">p.74<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakura-airi-y1v5-p54-1\">← Before: Ch.4 §4: Last place, then the worst pair<\/button><\/div><\/article>"},{"i":"sc-shibata-sou-y1v5-p68-1","v":"y1v5","y":1,"o":6,"k":"","w":"hirata-yousuke ayanokouji-kiyotaka shibata-sou","q":"shibata so ch 5  5  the fastest in class b shibata scores on a brilliant arc during the practice the trio watches  then joins their group the next day  better than hirata by his own senior s account    hirata kun says that shibata kun is better than he is  remembers ayanokoji s name and asks if he is on a date with the two girls  hirata s warning to the group   we need to be especially wary of shibata kun  he s the fastest in class b  makes no attempt to hide his speed   whether for ichinose s class b or from personality","h":"<article class=\"card\" id=\"sc-shibata-sou-y1v5-p68-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shibata-sou.html#sc-shibata-sou-y1v5-p68-1\">Ch.5 §5: The fastest in Class B<\/a><\/span><span class=\"meta\">Y1V5 · p.68–85<\/span><span class=\"by\">notes on <a href=\"../../../people/shibata-sou.html\">Shibata Sō<\/a><\/span><\/h3><p class=\"setup\">Shibata scores on a brilliant arc during the practice the trio watches, then joins their group the next day.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Better than Hirata by his own senior’s account — “Hirata-kun says that Shibata-kun is better than he is.”<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Remembers Ayanokōji’s name and asks if he is on a date with the two girls.<span class=\"pg\">p.79<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Hirata’s warning to the group: “We need to be especially wary of Shibata-kun. He’s the fastest in Class B.”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Makes no attempt to hide his speed — whether for Ichinose’s Class B or from personality.<span class=\"pg\">p.76–80<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-sudou-ken-y1v5-p68-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"horikita-suzune sudou-ken","q":"sudo ken ch 5  5  noodles  first names  and the anchor he gives up sudou spends saturday morning in ayanokoji s room with ike and yamauchi  cup noodles in hand  talking about horikita   what flavor did you get   trade with me  please  an untagged classmate asks  do you plan on telling horikita  and sudou answers  huh  the hell is this about   that depends on how the festival goes    on making a move after the bet   there ain t none of the first years better than me at sports   let s talk about my future with suzune  given the relay anchor  then pulled aside when horikita asks for it  not convinced   it s just  y know  the anchor position goes to the fastest team member   i ain t convinced  this ain t like you  horikita  yields once the brother reason is on the table    i don t mind handin  it over to you","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v5-p68-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sudou-ken.html#sc-sudou-ken-y1v5-p68-1\">Ch.5 §5: Noodles, first names, and the anchor he gives up<\/a><\/span><span class=\"meta\">Y1V5 · p.68–85<\/span><span class=\"by\">notes on <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/span><\/h3><p class=\"setup\">Sudou spends Saturday morning in Ayanokōji’s room with Ike and Yamauchi, cup noodles in hand, talking about Horikita.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “What flavor did you get?”<span class=\"pg\">p.72<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “Trade with me, please?”<span class=\"pg\">p.72<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> An untagged classmate asks “Do you plan on telling Horikita?” and Sudou answers “Huh? The hell is this about?”<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “That depends on how the festival goes.” — on making a move after the bet.<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “there ain’t none of the first years better than me at sports,”<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “Let’s talk about my future with Suzune,”<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Given the relay anchor, then pulled aside when Horikita asks for it.<span class=\"pg\">p.82<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Not convinced: “It’s just, y’know, the anchor position goes to the fastest team member.”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “I ain’t convinced. This ain’t like you, Horikita,”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Yields once the brother reason is on the table — “I don’t mind handin’ it over to you,”<span class=\"pg\">p.84<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p54-1\">← Before: Ch.4 §4: The name bet and the leader’s first week<\/button><\/div><\/article>"},{"i":"sc-yamauchi-haruki-y1v5-p68-1","v":"y1v5","y":1,"o":6,"k":"","w":"sakura-airi sakayanagi-arisu ayanokouji-kiyotaka yamauchi-haruki","q":"yamauchi haruki ch 5  5  the sakura defeat still stings yamauchi is in the saturday noodle group  forced smiling through the talk  still nursing the summer confession defeat    y yeah  to ike s teasing  passes on the class leader rumor   from what i ve heard  people say that she s the class leader  presses the girlfriend question   you don t have a girlfriend  do you","h":"<article class=\"card\" id=\"sc-yamauchi-haruki-y1v5-p68-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yamauchi-haruki.html#sc-yamauchi-haruki-y1v5-p68-1\">Ch.5 §5: The Sakura defeat still stings<\/a><\/span><span class=\"meta\">Y1V5 · p.68–85<\/span><span class=\"by\">notes on <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a><\/span><\/h3><p class=\"setup\">Yamauchi is in the Saturday noodle group, forced-smiling through the talk.<\/p><p class=\"with\">with <a href=\"../../../people/sakura-airi.html\">Sakura Airi<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakura Airi<\/b> Still nursing the summer confession defeat — “Y-yeah.” to Ike’s teasing.<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Passes on the class-leader rumor: “From what I’ve heard, people say that she’s the class leader.”<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Presses the girlfriend question: “You don’t have a girlfriend, do you?”<span class=\"pg\">p.73<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamauchi-haruki-y1v5-p54-1\">← Before: Ch.4 §4: On the losing end of the demo<\/button><\/div><\/article>"}];
